<script setup>
import CityHud from '../components/CityHud.vue'

const props = defineProps({ controls: { type: Object, required: true } })
// Computed ngày/giờ vẫn ghi về cùng state shading; đóng hoặc ẩn HUD không đổi cấu hình bản đồ.
const { shading, shadingDate, shadingTime, sunPosition, shadingError, shadingLayers, timeZone } = props.controls
</script>

<template>
  <!-- Bố cục: HUD phái sinh có lịch, đồng hồ, ánh sáng và kết quả tính mặt trời; dùng cùng khung thu gọn với HUD chính. -->
  <CityHud title="Shading settings">
    <VaDateInput
      v-model="shadingDate"
      label="Date"
      aria-label="Shading date"
      :start-year="1950"
      v-bind="{
        'child:prevButton': { icon: 'ion-md-arrow-back' },
        'child:nextButton': { icon: 'ion-md-arrow-forward' },
      }"
      icon="ion-md-calendar"
      aria-toggle-dropdown-label="Open shading calendar"
    />
    <VaTimeInput
      v-model="shadingTime"
      label="Local time"
      aria-label="Shading time"
      icon="ion-md-time"
      aria-toggle-dropdown-label="Open shading clock"
      view="minutes"
    />
    <p class="text-xs text-secondary">{{ timeZone }}</p>
    <VaSwitch v-model="shading.sunlight" label="Sun light" aria-label="Sun light" size="small" />
    <p v-if="sunPosition" class="text-xs" data-testid="sun-position">
      Sun altitude {{ sunPosition.altitude.toFixed(1) }}° · Azimuth {{ sunPosition.azimuth.toFixed(1) }}°
    </p>
    <VaAlert v-if="sunPosition && sunPosition.altitude <= 0" color="info" dense outline class="mb-0 text-xs"
      >Sun below horizon · No shadows</VaAlert
    >
    <div class="flex flex-wrap gap-1">
      <VaChip v-for="entry in shadingLayers" :key="entry.id" size="small" flat readonly>{{ entry.label }}</VaChip>
    </div>
    <VaAlert v-if="!shadingLayers.length" color="info" dense outline class="mb-0 text-xs"
      >Enable a 3D building layer to see shadows.</VaAlert
    >
    <VaAlert v-if="shadingError" color="danger" dense outline class="mb-0 text-xs" data-testid="shading-error">{{
      shadingError
    }}</VaAlert>
  </CityHud>
</template>
