import * as THREE from 'three'
import mapboxgl from 'mapbox-gl'
import { sampleVelocity, sliceInfo, windContours } from './cfdData.js'

export const WIND_LAYER_ID = 'city-visualize-cfd'

/** Input: tốc độ, range. Output: RGB 0..1, giữ công thức màu vận tốc của wind/index.js cũ. */
export function windColor(value, min, max, out = [0, 0, 0]) {
  const t = Math.max(0, Math.min(1, (value - min) / (max - min || 1)))
  const g = 4.4 * t + 0.8
  out[0] = Math.max(0, (3 - Math.abs(g - 4) - Math.abs(g - 5)) / 2)
  out[1] = Math.max(0, (4 - Math.abs(g - 2) - Math.abs(g - 4)) / 2)
  out[2] = Math.max(0, (3 - Math.abs(g - 1) - Math.abs(g - 2)) / 2)
  return out
}

/**
 * Input: tốc độ từng hạt và RGB Float32Array cấp sẵn. Output: ghi màu xanh → lục → vàng → đỏ vào out.
 * Lấy range của toàn bộ hạt trước khi tô để lát cắt không mất màu vì cực trị ở ngoài lát; không phụ thuộc thứ tự hạt như vòng lặp cũ.
 */
export function particleColors(speeds, out) {
  let min = Infinity,
    max = -Infinity
  for (const speed of speeds) {
    min = Math.min(min, speed)
    max = Math.max(max, speed)
  }
  const color = [0, 0, 0]
  for (let i = 0; i < speeds.length; i++) out.set(windColor(speeds[i], min, max, color), i * 3)
  return out
}

/**
 * Input: field đã validate và settings reactive (origin, side, level, slice, speed, pointSize, paused, contours).
 * Output: Mapbox CustomLayerInterface dùng Three BufferGeometry, không truy cập sourceCaches/painter.
 * X đông, Y lên, Z nam; origin là tâm ngang của lưới như code cũ. Ẩn/xóa layer giải phóng toàn bộ GPU resource.
 */
export function createWindLayer(field, settings) {
  let map, renderer, scene, camera, points, lines, texture
  let contourTimer,
    lastFrame = 0
  const extent = [(field.width - 1) * field.hx, (field.height - 1) * field.hy, (field.depth - 1) * field.hz]
  const count = 40000
  const positions = new Float32Array(count * 3),
    colors = new Float32Array(count * 3),
    speeds = new Float64Array(count),
    ages = new Float32Array(count)
  const point = [0, 0, 0],
    velocity = [0, 0, 0],
    color = [0, 0, 0]
  const transform = new THREE.Matrix4(),
    projection = new THREE.Matrix4()
  const rotation = new THREE.Matrix4().makeRotationX(Math.PI / 2)
  const scale = new THREE.Vector3()
  const offsetX = extent[0] / 2,
    offsetZ = extent[2] / 2

  function respawn(i, info) {
    for (let axis = 0; axis < 3; axis++) point[axis] = Math.random() * extent[axis]
    if (settings.slice) point[info.axis] = settings.level * info.spacing
    positions[i] = point[0] - offsetX
    positions[i + 1] = point[1]
    positions[i + 2] = point[2] - offsetZ
    ages[i / 3] = Math.random() * 10
    sampleVelocity(field, point, velocity)
    speeds[i / 3] = Math.hypot(...velocity)
  }

  function clearLines() {
    if (!lines) return
    scene.remove(lines)
    lines.geometry.dispose()
    lines.material.dispose()
    lines = null
  }

  /** Settings mặt/level mới -> reset particle plane và rebuild contour; debounce tránh dựng mesh ở mỗi tick slider. */
  function configure() {
    if (!points) return
    const info = sliceInfo(field, settings.side)
    for (let i = 0; i < positions.length; i += 3) respawn(i, info)
    points.geometry.attributes.position.needsUpdate = true
    // Gán cả màu khi đổi lát/style lúc Pause; không đợi frame chuyển động đầu tiên.
    particleColors(speeds, colors)
    points.geometry.attributes.color.needsUpdate = true
    clearTimeout(contourTimer)
    clearLines()
    if (settings.contours)
      contourTimer = setTimeout(() => {
        if (!map || !settings.contours) return
        const contour = windContours(field, settings.side, settings.level, settings.contourLevels)
        const vertices = Float32Array.from(contour.positions),
          lineColors = new Float32Array(vertices.length)
        for (let i = 0; i < vertices.length; i += 3) {
          vertices[i] -= offsetX
          vertices[i + 2] -= offsetZ
          windColor(contour.values[i / 3], field.min, field.max, color)
          lineColors.set(color, i)
        }
        const geometry = new THREE.BufferGeometry()
        geometry.setAttribute('position', new THREE.BufferAttribute(vertices, 3))
        geometry.setAttribute('color', new THREE.BufferAttribute(lineColors, 3))
        lines = new THREE.LineSegments(geometry, new THREE.LineBasicMaterial({ vertexColors: true, depthTest: true }))
        lines.frustumCulled = false
        scene.add(lines)
        map.triggerRepaint()
      }, 150)
    map.triggerRepaint()
  }

  return {
    id: WIND_LAYER_ID,
    type: 'custom',
    renderingMode: '3d',
    configure,
    onAdd(target, gl) {
      map = target
      scene = new THREE.Scene()
      camera = new THREE.Camera()
      // Texture tạo cục bộ để CFD không phụ thuộc thêm một URL sprite ngoài dự án.
      const canvas = document.createElement('canvas')
      canvas.width = canvas.height = 32
      const ctx = canvas.getContext('2d')
      const gradient = ctx.createRadialGradient(16, 16, 0, 16, 16, 16)
      gradient.addColorStop(0, '#fff')
      gradient.addColorStop(0.5, '#fff')
      gradient.addColorStop(1, 'transparent')
      ctx.fillStyle = gradient
      ctx.fillRect(0, 0, 32, 32)
      texture = new THREE.CanvasTexture(canvas)
      const geometry = new THREE.BufferGeometry()
      geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3).setUsage(THREE.DynamicDrawUsage))
      geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3).setUsage(THREE.DynamicDrawUsage))
      points = new THREE.Points(
        geometry,
        new THREE.PointsMaterial({
          size: settings.pointSize,
          sizeAttenuation: false,
          map: texture,
          vertexColors: true,
          transparent: true,
          alphaTest: 0.15,
          depthTest: true,
          depthWrite: true,
        }),
      )
      points.frustumCulled = false
      scene.add(points)
      renderer = new THREE.WebGLRenderer({ canvas: map.getCanvas(), context: gl, antialias: true })
      renderer.autoClear = false
      configure()
    },
    render(gl, matrix) {
      const now = performance.now(),
        dt = Math.min(lastFrame ? (now - lastFrame) / 1000 : 1 / 60, 0.05) * 60 * settings.speed
      lastFrame = now
      const info = sliceInfo(field, settings.side)
      if (!settings.paused) {
        for (let i = 0; i < positions.length; i += 3) {
          point[0] = positions[i] + offsetX
          point[1] = positions[i + 1]
          point[2] = positions[i + 2] + offsetZ
          if (ages[i / 3] > 15 || !sampleVelocity(field, point, velocity)) {
            respawn(i, info)
            continue
          }
          speeds[i / 3] = Math.hypot(...velocity)
          for (let axis = 0; axis < 3; axis++) point[axis] += velocity[axis] * dt
          if (settings.slice) point[info.axis] = settings.level * info.spacing
          positions[i] = point[0] - offsetX
          positions[i + 1] = point[1]
          positions[i + 2] = point[2] - offsetZ
          ages[i / 3] += dt
        }
        particleColors(speeds, colors)
        points.geometry.attributes.position.needsUpdate = true
        points.geometry.attributes.color.needsUpdate = true
      }
      points.material.size = settings.pointSize
      const origin = mapboxgl.MercatorCoordinate.fromLngLat(settings.origin)
      const unit = origin.meterInMercatorCoordinateUnits()
      transform
        .makeTranslation(origin.x, origin.y, origin.z)
        .scale(scale.set(unit, -unit, unit))
        .multiply(rotation)
      camera.projectionMatrix.copy(projection.fromArray(matrix)).multiply(transform)
      renderer.resetState()
      renderer.render(scene, camera)
      // Mapbox sở hữu vòng render: pause/ẩn HUD không tạo thêm requestAnimationFrame riêng.
      if (!settings.paused && settings.speed > 0) map.triggerRepaint()
    },
    onRemove() {
      clearTimeout(contourTimer)
      clearLines()
      points?.geometry.dispose()
      points?.material.dispose()
      texture?.dispose()
      renderer?.dispose()
      map = null
      points = null
      renderer = null
    },
  }
}
