import { readLines, validateCrs } from './csvBesData.js'

export const windDemo = {
  url: 'https://raw.githubusercontent.com/supcn/public/main/ev2.json',
  width: 201,
  height: 51,
  depth: 201,
  hx: 5,
  hy: 4,
  hz: 5,
  origin: [-73.57825, 45.4958],
}

/** Input: GeoJSON Point text positionSetting.txt. Output: [longitude, latitude]; CRS khai báo khác WGS84 bị từ chối; properties.projection mô tả hệ trục STL, không đổi CRS của Point. */
export function readPosition(text) {
  const feature = JSON.parse(text.replace(/^\uFEFF/, ''))
  validateCrs(feature)
  const point = feature?.type === 'Feature' && feature.geometry?.type === 'Point' ? feature.geometry.coordinates : null
  if (
    !Array.isArray(point) ||
    !Number.isFinite(point[0]) ||
    !Number.isFinite(point[1]) ||
    Math.abs(point[0]) > 180 ||
    Math.abs(point[1]) > 85.051129
  )
    throw new Error('Position file must be a WGS84 GeoJSON Point feature.')
  return point.slice(0, 2)
}

function gridSize(grid) {
  const dimensions = [grid.width, grid.height, grid.depth]
  const count = dimensions.reduce((a, b) => a * b, 1)
  if (!dimensions.every((n) => Number.isInteger(n) && n > 1) || !Number.isSafeInteger(count) || count > 10000000)
    throw new Error('CFD grid dimensions must be integers above 1 and contain at most 10 million nodes.')
  return count
}

function finish(grid) {
  let min = Infinity,
    max = -Infinity
  for (let i = 0; i < grid.velocity.length; i += 3) {
    const speed = Math.hypot(grid.velocity[i], grid.velocity[i + 1], grid.velocity[i + 2])
    if (!Number.isFinite(speed)) throw new Error('CFD velocities must be finite numbers.')
    min = Math.min(min, speed)
    max = Math.max(max, speed)
  }
  return { ...grid, min, max }
}

/** Input: JSON demo [[u,v,w], ...], cấu hình grid. Output: một Float32Array theo thứ tự x nhanh nhất, rồi y, rồi z. */
export function readWindJson(samples, grid = windDemo) {
  const count = gridSize(grid)
  if (!Array.isArray(samples) || samples.length !== count)
    throw new Error('CFD JSON must contain exactly ' + count + ' velocity vectors.')
  const velocity = new Float32Array(count * 3)
  samples.forEach((sample, index) => {
    if (!Array.isArray(sample) || sample.length < 3 || !sample.slice(0, 3).every(Number.isFinite))
      throw new Error('Invalid CFD velocity at node ' + index + '.')
    velocity.set(sample.slice(0, 3), index * 3)
  })
  return finish({
    width: grid.width,
    height: grid.height,
    depth: grid.depth,
    hx: grid.hx,
    hy: grid.hy,
    hz: grid.hz,
    velocity,
  })
}

/**
 * Input: Tecplot-style VTK/DAT text: VARIABLES..., ZONE I=nx,J=ny,K=nz, rồi x y z u v w mỗi nút.
 * Output: kích thước, bước lưới mét và Float32Array vận tốc; kiểm tra đủ số nút và lưới Cartesian đều.
 * Đây là định dạng controller cũ đọc, không phải parser VTK binary/XML tổng quát.
 */
// shortcut: giới hạn 10 triệu nút và giữ field trong RAM; dùng worker/GPU field khi cần dataset lớn hơn.
export async function readWind(file, options = {}) {
  let grid = null,
    count = 0,
    node = 0,
    start = null
  const spacing = [null, null, null]
  for await (const raw of readLines(file, options)) {
    const line = raw.trim().replace(/^\uFEFF/, '')
    if (!line || line.startsWith('#')) continue
    if (!grid) {
      if (!/\bZONE\b/i.test(line)) continue
      const dimensions = Object.fromEntries(
        [...line.matchAll(/\b([IJK])\s*=\s*(\d+)/gi)].map((m) => [m[1].toUpperCase(), Number(m[2])]),
      )
      grid = { width: dimensions.I, height: dimensions.J, depth: dimensions.K }
      count = gridSize(grid)
      grid.velocity = new Float32Array(count * 3)
      continue
    }
    const cells = line.split(/\s+/).map(Number)
    if (cells.length < 6 || !cells.slice(0, 6).every(Number.isFinite) || node >= count)
      throw new Error('CFD data rows must contain x y z u v w and match I*J*K.')
    if (!start) start = cells.slice(0, 3)
    const x = node % grid.width,
      y = Math.floor(node / grid.width) % grid.height,
      z = Math.floor(node / grid.width / grid.height)
    if (node === 1) spacing[0] = cells[0] - start[0]
    if (node === grid.width) spacing[1] = cells[1] - start[1]
    if (node === grid.width * grid.height) spacing[2] = cells[2] - start[2]
    for (const [axis, index] of [x, y, z].entries()) {
      const step = spacing[axis]
      if (
        step !== null &&
        (!(step > 0) || Math.abs(cells[axis] - start[axis] - index * step) > Math.max(0.00001, Math.abs(step) * 0.0001))
      )
        throw new Error('CFD requires an ascending, uniform Cartesian grid with x fastest, then y, then z.')
      if (step === null && Math.abs(cells[axis] - start[axis]) > 0.00001)
        throw new Error('CFD nodes are not ordered x, then y, then z.')
    }
    grid.velocity.set(cells.slice(3, 6), node * 3)
    node++
  }
  if (!grid || node !== count || !spacing.every((n) => n > 0))
    throw new Error('CFD file is missing ZONE dimensions, grid spacing, or complete data rows.')
  return finish({ ...grid, hx: spacing[0], hy: spacing[1], hz: spacing[2] })
}

/** Input: grid, vị trí [x,y,z] mét từ góc lưới, out=[0,0,0]. Output: vận tốc nội suy trilinear vào out; ngoài grid -> null. */
export function sampleVelocity(grid, point, out = [0, 0, 0]) {
  const qx = point[0] / grid.hx,
    qy = point[1] / grid.hy,
    qz = point[2] / grid.hz
  if (
    !Number.isFinite(qx) ||
    !Number.isFinite(qy) ||
    !Number.isFinite(qz) ||
    qx < 0 ||
    qy < 0 ||
    qz < 0 ||
    qx > grid.width - 1 ||
    qy > grid.height - 1 ||
    qz > grid.depth - 1
  )
    return null
  const ix = Math.min(grid.width - 2, Math.floor(qx)),
    iy = Math.min(grid.height - 2, Math.floor(qy)),
    iz = Math.min(grid.depth - 2, Math.floor(qz))
  const tx = qx - ix,
    ty = qy - iy,
    tz = qz - iz
  out.fill(0)
  for (let z = 0; z < 2; z++)
    for (let y = 0; y < 2; y++)
      for (let x = 0; x < 2; x++) {
        const weight = (x ? tx : 1 - tx) * (y ? ty : 1 - ty) * (z ? tz : 1 - tz)
        const offset = ((iz + z) * grid.width * grid.height + (iy + y) * grid.width + ix + x) * 3
        out[0] += grid.velocity[offset] * weight
        out[1] += grid.velocity[offset + 1] * weight
        out[2] += grid.velocity[offset + 2] * weight
      }
  return out
}

/** Input: grid + mặt XY/YZ/XZ. Output: trục bị cố định, số level tối đa và bước mét theo mặt đang chọn. */
export function sliceInfo(grid, side) {
  const axis = { XY: 2, YZ: 0, XZ: 1 }[side]
  if (axis === undefined) throw new Error('Choose an XY, YZ or XZ slice.')
  return { axis, max: [grid.width, grid.height, grid.depth][axis] - 1, spacing: [grid.hx, grid.hy, grid.hz][axis] }
}

/**
 * Input: field, mặt cắt, level index và số đường. Output: segments {positions:[x,y,z,...], values:[speed,...]} để THREE.LineSegments vẽ.
 * Chia mỗi ô thành 2 tam giác để xử lý cả saddle/4 giao điểm; level được nhân spacing ra mét một lần duy nhất.
 */
export function windContours(grid, side, level, intervals) {
  const info = sliceInfo(grid, side)
  const axes = [0, 1, 2].filter((axis) => axis !== info.axis)
  const sizes = [grid.width, grid.height, grid.depth],
    spacing = [grid.hx, grid.hy, grid.hz]
  const positions = [],
    values = []
  const velocity = [0, 0, 0]
  const point = (a, b) => {
    const p = [0, 0, 0]
    p[info.axis] = level * info.spacing
    p[axes[0]] = a * spacing[axes[0]]
    p[axes[1]] = b * spacing[axes[1]]
    return p
  }
  const speed = (p) => {
    sampleVelocity(grid, p, velocity)
    return Math.hypot(...velocity)
  }
  if (grid.min === grid.max) return { positions, values }
  for (let b = 0; b < sizes[axes[1]] - 1; b++)
    for (let a = 0; a < sizes[axes[0]] - 1; a++) {
      const corners = [point(a, b), point(a + 1, b), point(a + 1, b + 1), point(a, b + 1)]
      const speeds = corners.map(speed)
      for (let i = 1; i <= intervals; i++) {
        const threshold = grid.min + ((grid.max - grid.min) * i) / (intervals + 1)
        for (const triangle of [
          [0, 1, 2],
          [0, 2, 3],
        ]) {
          const hits = []
          for (let edge = 0; edge < 3; edge++) {
            const x = triangle[edge],
              y = triangle[(edge + 1) % 3]
            if (speeds[x] < threshold === speeds[y] < threshold) continue
            const t = (threshold - speeds[x]) / (speeds[y] - speeds[x])
            hits.push(corners[x].map((n, axis) => n + t * (corners[y][axis] - n)))
          }
          if (hits.length === 2) {
            positions.push(...hits[0], ...hits[1])
            values.push(threshold, threshold)
          }
        }
      }
    }
  return { positions, values }
}
