import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useColors } from 'vuestic-ui'
import mapboxgl from 'mapbox-gl'
import { useMapControls } from './controls/useMapControls.js'
import { useMapLayers } from './layer/useMapLayers.js'
import { useLayerDetails } from './layer/useLayerDetails.js'
import { useVisualization } from './visualize/useVisualization.js'
import { useStlExport } from './export/useStlExport.js'
import { useCityImport } from './import/useCityImport.js'

/**
 * Input: CityView gắn mapElement và DOM refs của controls/details; VITE_MAPBOX_TOKEN là public token pk.
 * Output: trạng thái map và các module độc lập controls/layers/details/importer/visualization/exporter.
 * Ví dụ city.layers.layerVisibility['city-concordia-2d']=true -> watcher của Layer bật lớp 2D.
 * File này chỉ tạo/hủy một Mapbox, phân phối style.load/error và nối cùng getMap/ready cho các module.
 * ready=true nghĩa là style đã dựng xong các lớp, chưa bảo đảm mọi tile của viewport đã tải.
 * onBeforeUnmount của module đăng ký trước owner: abort file/fetch, hủy Draw/GPU/popup rồi mới map.remove().
 */
export function useCityMap() {
  const mapElement = ref(null)
  const initialized = ref(false)
  const ready = ref(false)
  const error = ref('')
  const { currentPresetName } = useColors()
  const isDark = computed(() => currentPresetName.value === 'dark')
  const accessToken = import.meta.env.VITE_MAPBOX_TOKEN?.trim()
  let map, resizeObserver
  const getMap = () => map
  const controls = useMapControls({ getMap, accessToken })
  const importer = useCityImport({ getMap, ready })
  const layers = useMapLayers({ getMap, ready, importer })
  const visualization = useVisualization({ getMap, ready, layerVisibility: layers.layerVisibility })
  const exporter = useStlExport({ getMap, ready, visualization, importer })
  const details = useLayerDetails({
    getMap,
    ready,
    layerVisibility: layers.layerVisibility,
    overlayVisibility: layers.overlayVisibility,
    handlesClick: exporter.handlesClick,
    importer,
  })

  /** Đổi nền -> khóa thao tác trong lúc tải; mỗi module giữ state để phục hồi theo style mới. */
  watch(controls.mapStyle, (style) => {
    if (!map) return
    details.closeFeature()
    ready.value = false
    error.value = ''
    layers.clearErrors()
    exporter.beforeStyleChange()
    map.setStyle(style, { diff: false })
  })

  onMounted(() => {
    if (!accessToken?.startsWith('pk.')) {
      error.value = 'Set VITE_MAPBOX_TOKEN to a public Mapbox token (pk.) and restart the dev server.'
      return
    }
    try {
      // Tọa độ WGS84 [longitude, latitude], zoom 11 tại Montréal; theme HUD độc lập với basemap.
      map = new mapboxgl.Map({
        container: mapElement.value,
        accessToken,
        style: controls.mapStyle.value,
        center: [-73.5673, 45.5017],
        zoom: 11,
        pitch: 0,
        bearing: 0,
        antialias: true,
        attributionControl: false,
      })
      initialized.value = true
      map.on('style.load', () => {
        try {
          layers.restore()
        } catch {
          error.value = 'Could not initialize map layers. Try another basemap.'
        }
        ready.value = true
        importer.restore()
        visualization.restore()
        exporter.restore()
        layers.shadingControls.apply()
      })
      // Module nhận sourceId trước; chỉ lỗi không thuộc module nào mới hiện ở trạng thái basemap.
      map.on('error', (event) => {
        if (
          importer.sourceError(event.sourceId) ||
          visualization.sourceError(event.sourceId) ||
          exporter.sourceError(event.sourceId) ||
          layers.sourceError(event.sourceId)
        )
          return
        error.value = 'Could not load Mapbox. Check your token, connection and allowed domains.'
      })
      details.attach()
      map.on('moveend', layers.shadingControls.apply)
      controls.attach()
      resizeObserver = new ResizeObserver(() => map?.resize())
      resizeObserver.observe(mapElement.value)
    } catch {
      error.value = 'Could not initialize Mapbox. Check your token and browser WebGL support.'
    }
  })

  onBeforeUnmount(() => {
    resizeObserver?.disconnect()
    map?.remove()
    map = null
  })

  return { mapElement, initialized, ready, error, isDark, controls, layers, details, importer, visualization, exporter }
}
