<script setup>
import CityHud from '../components/CityHud.vue'
import CsvSettingsHud from './CsvSettingsHud.vue'
import BesBemSettingsHud from './BesBemSettingsHud.vue'
import CfdSettingsHud from './CfdSettingsHud.vue'
const props = defineProps({ visualization: { type: Object, required: true }, ready: Boolean })
const { csvBes, cfd } = props.visualization
</script>

<template>
  <!-- Bố cục: Công tắc CSV/BES dùng csvBes, CFD dùng cfd; mỗi controller sở hữu state và HUD phái sinh riêng. -->
  <CityHud title="Visualize" collapsed>
    <VaList class="space-y-1">
      <VaListItem v-for="entry in csvBes.entries" :key="entry.id" class="rounded-md p-2" tabindex="-1">
        <VaListItemSection
          ><VaListItemLabel :lines="2" class="text-xs font-semibold">{{
            entry.label
          }}</VaListItemLabel></VaListItemSection
        >
        <VaListItemSection icon
          ><VaSwitch v-model="entry.enabled" :aria-label="entry.label" :disabled="!ready" size="small"
        /></VaListItemSection>
      </VaListItem>
      <VaListItem class="rounded-md p-2" tabindex="-1">
        <VaListItemSection
          ><VaListItemLabel class="text-xs font-semibold">CFD / Wind</VaListItemLabel></VaListItemSection
        >
        <VaListItemSection icon
          ><VaSwitch v-model="cfd.state.enabled" aria-label="CFD / Wind" :disabled="!ready" size="small"
        /></VaListItemSection>
      </VaListItem>
    </VaList>
  </CityHud>
  <Teleport to="#city-derived-huds" defer>
    <template v-for="entry in csvBes.entries" :key="entry.id">
      <BesBemSettingsHud
        v-if="entry.enabled && entry.id === 'bem'"
        :entry="entry"
        :visualization="csvBes"
        :ready="ready"
      />
      <CsvSettingsHud v-else-if="entry.enabled" :entry="entry" :visualization="csvBes" :ready="ready" />
    </template>
    <CfdSettingsHud v-if="cfd.state.enabled" :cfd="cfd" :ready="ready" />
  </Teleport>
</template>
