<script setup>
import CityHud from '../components/CityHud.vue'
const props = defineProps({ controller: { type: Object, required: true }, ready: Boolean })
const state = props.controller.state
</script>

<template>
  <!-- Nhiều STL có tọa độ độc lập; chọn file để xem thông số, Apply/Locate đưa lên map, Remove giải phóng GPU. -->
  <CityHud title="STL import settings">
    <VaFileUpload
      v-model="state.files"
      data-testid="import-stl-files"
      file-types=".stl"
      upload-button-text="STL files"
      multiple
      :disabled="state.loading"
      @update:modelValue="controller.load($event)"
    />
    <VaProgressBar v-if="state.loading" indeterminate aria-label="Reading imported STL" />
    <p class="text-xs text-secondary">
      STL files do not contain a map location. Use the original origin or the matching positionSetting.txt.
    </p>
    <VaForm
      v-for="(model, index) in state.models"
      :key="model.id"
      novalidate
      class="space-y-3"
      @submit.prevent="controller.apply(model)"
    >
      <VaDivider />
      <p class="text-xs font-semibold break-words">{{ model.name }}</p>
      <p v-if="model.parsed" class="text-xs" data-testid="import-stl-summary">
        {{ model.parsed.format }} · {{ model.parsed.solids.length }} solids ·
        {{ model.parsed.triangleCount }} triangles{{ model.applied ? ' · On map' : '' }}
      </p>
      <template v-if="model.parsed">
        <!-- File vị trí đi kèm bản export khôi phục origin/projection, không tự dịch tâm mô hình. -->
        <VaFileUpload
          v-model="model.positionFile"
          :data-testid="'import-stl-position-' + (index + 1)"
          file-types=".txt,.json,.geojson"
          upload-button-text="Load positionSetting.txt"
          :disabled="state.loading || model.positionLoading"
          @update:modelValue="controller.loadPosition(model, $event)"
        />
        <p class="text-xs text-secondary">
          Load the matching position file, then Apply model. Coordinates locate the STL origin.
        </p>
        <div class="grid grid-cols-2 gap-2">
          <VaInput
            v-model="model.lng"
            type="number"
            label="Longitude"
            :input-aria-label="'Imported STL ' + (index + 1) + ' longitude'"
          />
          <VaInput
            v-model="model.lat"
            type="number"
            label="Latitude"
            :input-aria-label="'Imported STL ' + (index + 1) + ' latitude'"
          />
        </div>
        <VaSelect
          v-model="model.projection"
          label="Projection"
          :aria-label="'Imported STL ' + (index + 1) + ' projection'"
          text-by="title"
          value-by="value"
          :options="[
            { title: 'Local metres', value: 'local' },
            { title: 'Legacy Web Mercator', value: 'web-mercator' },
          ]"
        />
        <div class="flex flex-wrap gap-2">
          <VaButton type="submit" size="small" :disabled="!ready || state.loading || model.positionLoading"
            >Apply model</VaButton
          >
          <VaButton
            size="small"
            preset="secondary"
            :disabled="!ready || model.positionLoading"
            @click="controller.apply(model, true)"
            >Locate model</VaButton
          >
        </div>
      </template>
      <VaButton size="small" preset="secondary" :disabled="state.loading" @click="controller.remove(model)"
        >Remove model</VaButton
      >
      <VaAlert v-if="model.error" color="danger" dense outline class="mb-0 text-xs break-words">{{
        model.error
      }}</VaAlert>
    </VaForm>
  </CityHud>
</template>
