import * as chromatic from 'd3-scale-chromatic'
import { coordEach } from '@turf/meta'
import {
  joinKey,
  mergeCsvGeoJson,
  parseCsv,
  parseGeoJson,
} from '../../preprocessing/csv-geojson-merge/csvGeoJsonMerger.js'

export { parseCsv, joinKey }
export const paletteNames = Object.keys(chromatic)
  .filter((name) => name.startsWith('interpolate'))
  .map((name) => name.slice(11))
  .sort()

/** Input: ' 12.5 ' -> 12.5; '', null, '12m', Infinity -> null. Không tô dữ liệu thiếu thành số 0. */
export function numeric(value) {
  if (!['string', 'number'].includes(typeof value) || String(value).trim() === '') return null
  const result = Number(value)
  return Number.isFinite(result) ? result : null
}

/**
 * Input: Blob/File UTF-8. Output: từng dòng, giữ nguyên ký tự bị cắt giữa hai chunk và dòng cuối không có newline.
 * Ví dụ 'b0 123 28\r\n' -> 'b0 123 28'. signal hủy lượt đọc cũ; onProgress nhận 0..100.
 */
export async function* readLines(file, { signal, onProgress, chunkSize = 1024 * 1024 } = {}) {
  const decoder = new TextDecoder('utf-8', { fatal: true })
  let pending = ''
  for (let offset = 0; offset < file.size; offset += chunkSize) {
    signal?.throwIfAborted()
    const bytes = await file.slice(offset, offset + chunkSize).arrayBuffer()
    signal?.throwIfAborted()
    const lines = (pending + decoder.decode(bytes, { stream: true })).split('\n')
    pending = lines.pop()
    for (const line of lines) yield line.replace(/\r$/, '')
    onProgress?.(Math.min(100, Math.round(((offset + bytes.byteLength) / file.size) * 100)))
  }
  pending += decoder.decode()
  if (pending) yield pending.replace(/\r$/, '')
  signal?.throwIfAborted()
  onProgress?.(100)
}

/** Input: GeoJSON object có crs tùy chọn. Output: không trả giá trị; CRS khai báo khác WGS84 bị từ chối, không tự reproject. */
export function validateCrs(value) {
  if (!value?.crs) return
  const name = value.crs.properties?.name ?? (String(value.crs.properties?.code) === '4326' ? 'EPSG:4326' : '')
  if (typeof name !== 'string' || !/(?:^|:)4326$|(?:^|:)CRS84$/i.test(name))
    throw new Error('GeoJSON CRS must be WGS84 (EPSG:4326 or CRS84).')
}

/** Input: GeoJSON text WGS84. Output: collection chỉ Polygon/MultiPolygon; dữ liệu gốc không bị sửa. */
export function readPolygons(text) {
  const input = parseGeoJson(text)
  validateCrs(input)
  const features = input.features.filter((feature) => ['Polygon', 'MultiPolygon'].includes(feature.geometry?.type))
  if (!features.length) throw new Error('GeoJSON must contain Polygon or MultiPolygon features.')
  for (const [index, feature] of features.entries()) {
    validateCrs(feature)
    validateCrs(feature.geometry)
    const polygons = feature.geometry.type === 'Polygon' ? [feature.geometry.coordinates] : feature.geometry.coordinates
    if (!Array.isArray(polygons) || !polygons.length) throw new Error('Polygon ' + (index + 1) + ' is empty.')
    for (const rings of polygons) {
      if (!Array.isArray(rings) || !rings.length) throw new Error('Polygon rings are missing.')
      for (const ring of rings) {
        if (
          !Array.isArray(ring) ||
          ring.length < 4 ||
          ring[0]?.[0] !== ring.at(-1)?.[0] ||
          ring[0]?.[1] !== ring.at(-1)?.[1]
        ) {
          throw new Error('Polygon rings must be closed and contain at least four coordinates.')
        }
      }
    }
    coordEach(feature, (point) => {
      if (
        !Array.isArray(point) ||
        !Number.isFinite(point[0]) ||
        !Number.isFinite(point[1]) ||
        Math.abs(point[0]) > 180 ||
        Math.abs(point[1]) > 85.051129
      ) {
        throw new Error('GeoJSON coordinates must be WGS84 [longitude, latitude] within the Mercator map.')
      }
    })
  }
  return {
    type: 'FeatureCollection',
    features: features.map((feature, index) => ({
      ...feature,
      properties: { ...feature.properties, auto_id: feature.properties?.auto_id ?? index },
    })),
  }
}

/** Input: collection có properties. Output: tên thuộc tính duy nhất theo thứ tự alphabet. */
export function propertyNames(collection) {
  return [...new Set(collection?.features.flatMap((feature) => Object.keys(feature.properties ?? {})) ?? [])].sort()
}

/**
 * Input: CSV + tên cột ID/value. Output: Map ID đã trim -> số hữu hạn; ID trùng giữ dòng hợp lệ đầu tiên như controller 2D/3D cũ.
 * '001' giữ nguyên, không tự biến thành '1'; các khóa 'length'/'__proto__' không ghi vào Object prototype.
 */
export function csvValues(csv, idKey, valueKey) {
  const id = csv.headers.indexOf(idKey),
    value = csv.headers.indexOf(valueKey)
  if (id < 0 || value < 0) throw new Error('Choose the CSV building ID and value columns.')
  const result = new Map()
  for (const row of csv.rows) {
    const key = joinKey(row[id]),
      number = numeric(row[value])
    if (key !== null && number !== null && !result.has(key)) result.set(key, number)
  }
  if (!result.size) throw new Error('No rows have both a building ID and a finite numeric value.')
  return result
}

/** Input: GeoJSON, CSV tùy chọn và các cột chọn. Output: polygon mới có __city_value để Mapbox tô màu; join không sửa file gốc. */
export function csvOverlay(collection, csv, csvKey, geoKey, valueKey) {
  const joined = csv ? mergeCsvGeoJson(csv, collection, csv.headers.indexOf(csvKey), geoKey).collection : collection
  return valuePolygons(joined, (feature) => numeric(feature.properties?.[valueKey]))
}

/** Input: polygon + hàm lấy số. Output: bản sao các feature có số hợp lệ, giữ thuộc tính/geometry để export về sau. */
export function valuePolygons(collection, getValue) {
  const features = []
  collection.features.forEach((feature, index) => {
    const value = getValue(feature, index)
    if (value !== null && Number.isFinite(value))
      features.push({ ...feature, properties: { ...feature.properties, __city_value: value } })
  })
  if (!features.length) throw new Error('No matching polygons have a finite numeric value.')
  return { type: 'FeatureCollection', features }
}

/**
 * Input: danh sách số và range/palette. Output: min/max, các stop Mapbox và gradient legend, dùng chung cho CSV/BES/CFD.
 * Range trống -> tự tính; min=max -> max=min+1 để không chia 0. Ví dụ [10,20], Oranges, 4 -> 5 stops.
 */
export function scalarStyle(values, { min = '', max = '', palette = 'Oranges', steps = 4 } = {}) {
  const interpolate = chromatic['interpolate' + palette]
  if (typeof interpolate !== 'function') throw new Error('Choose a valid color palette.')
  let lo = Infinity,
    hi = -Infinity
  for (const value of values)
    if (Number.isFinite(value)) {
      lo = Math.min(lo, value)
      hi = Math.max(hi, value)
    }
  if (!Number.isFinite(lo)) throw new Error('No finite values are available to display.')
  if (min !== '' || max !== '') {
    lo = numeric(min)
    hi = numeric(max)
    if (lo === null || hi === null) throw new Error('Set both color limits, or leave both empty for automatic limits.')
  }
  if (lo > hi) [lo, hi] = [hi, lo]
  if (lo === hi) hi = lo + 1
  const count = Number(steps)
  if (!Number.isInteger(count) || count < 1 || count > 35) throw new Error('Color intervals must be between 1 and 35.')
  const stops = [],
    colors = []
  for (let i = 0; i <= count; i++) {
    const color = interpolate(i / count)
    stops.push(lo + ((hi - lo) * i) / count, color)
    colors.push(color + ' ' + (i / count) * 100 + '%')
  }
  return { min: lo, max: hi, palette, stops, gradient: 'linear-gradient(to right, ' + colors.join(', ') + ')' }
}

/** Input: Map ID -> số và scalarStyle. Output: expression match trên nd (chuỗi hoặc số), building không match dùng trắng như code cũ. */
export function matchColors(values, style) {
  const expression = ['match', ['to-string', ['get', 'nd']]]
  const interpolate = chromatic['interpolate' + style.palette]
  for (const [key, value] of values)
    expression.push(key, interpolate(Math.max(0, Math.min(1, (value - style.min) / (style.max - style.min)))))
  expression.push('#ffffff')
  return expression
}

/**
 * Input: file BES text: 'building osm_id Temperature\ntimeloop0\nb0 123 28'.
 * Output: {variables:['Temperature'], steps:[{name:'timeloop0', values:Map('123' -> Float64Array([28]))}], buildingIds:['123']}.
 * Mỗi timestep giữ Map riêng để building thiếu không bị lệch thời gian/ID như nhánh GeoJSON cũ.
 */
// shortcut: đọc file theo chunk nhưng giữ kết quả BES trong RAM; dùng worker + lưu theo timestep khi dữ liệu thực vượt bộ nhớ trình duyệt.
export async function readBem(file, options = {}) {
  let variables = [],
    current = null
  const steps = [],
    names = new Set(),
    ids = new Set()
  let lineNumber = 0
  for await (const raw of readLines(file, options)) {
    lineNumber++
    const line = raw.trim().replace(/^\uFEFF/, '')
    if (!line || line.startsWith('#') || line.startsWith('//')) continue
    const cells = line.split(/\s+/)
    if (/^building/i.test(cells[0]) && (!current || /id|osm/i.test(cells[1] ?? ''))) {
      const next = cells.slice(2)
      if (!next.length || new Set(next).size !== next.length)
        throw new Error('BES header must contain unique variable names after the two building columns.')
      if (variables.length && next.join(' ') !== variables.join(' '))
        throw new Error('BES variable header changes within the file.')
      variables = next
    } else if (/^timeloop/i.test(cells[0])) {
      if (!variables.length) throw new Error('BES variable header is missing before the first timestep.')
      if (names.has(cells[0])) throw new Error('Duplicate BES timestep: ' + cells[0])
      names.add(cells[0])
      current = { name: cells[0], values: new Map() }
      steps.push(current)
    } else if (/^b/i.test(cells[0]) && current) {
      const id = joinKey(cells[1])
      if (id === null || cells.length !== variables.length + 2)
        throw new Error('Invalid BES row at line ' + lineNumber + '.')
      if (current.values.has(id)) throw new Error('Duplicate building ID ' + id + ' in ' + current.name + '.')
      current.values.set(
        id,
        Float64Array.from(cells.slice(2), (cell) => numeric(cell) ?? NaN),
      )
      ids.add(id)
    }
  }
  if (!steps.length || steps.some((step) => !step.values.size))
    throw new Error('BES must contain populated timeloop sections.')
  return { variables, steps, buildingIds: [...ids] }
}

/** Input: readBem result, index variable/timestep. Output: Map ID -> finite value; missing/non-numeric data is omitted. */
export function bemValues(data, variable, timestep) {
  if (!Number.isInteger(variable) || variable < 0 || variable >= data.variables.length || !data.steps[timestep])
    throw new Error('Choose a BES variable and timestep.')
  const values = new Map()
  for (const [id, row] of data.steps[timestep].values) if (Number.isFinite(row[variable])) values.set(id, row[variable])
  if (!values.size) throw new Error('This BES variable and timestep have no finite values.')
  return values
}
