import { GEOJSON_IMPORT_ID, REST_IMPORT_ID } from './importData.js'
import { useGeojsonImport } from './useGeojsonImport.js'
import { useStlImport } from './useStlImport.js'
import { useRestApiImport } from './useRestApiImport.js'

/** Input: cùng getMap/ready của City. Output: ba module Import riêng; restore không đọc lại file hoặc tự gọi API.
 * Export nhận snapshot STL và lớp GeoJSON đang bật. Popup nhận các lớp tương tác để hiển thị properties bằng text binding.
 */
export function useCityImport(options) {
  const geojson = useGeojsonImport(options),
    stl = useStlImport(options),
    rest = useRestApiImport(options)
  return {
    geojson,
    stl,
    rest,
    restore() {
      geojson.restore()
      stl.restore()
      rest.restore()
    },
    sourceError(id) {
      if (id === GEOJSON_IMPORT_ID) {
        geojson.state.error = 'Could not display the imported GeoJSON source.'
        return true
      }
      if (id === REST_IMPORT_ID) {
        rest.state.error = 'Could not display the imported REST source.'
        return true
      }
      return false
    },
    interactiveLayers: () => [
      GEOJSON_IMPORT_ID,
      ...['points', 'lines', 'polygons'].map((suffix) => REST_IMPORT_ID + '-' + suffix),
    ],
    featureDetails(feature) {
      return {
        kind: 'imported',
        layerId: feature.layer.id,
        title: feature.layer.id === GEOJSON_IMPORT_ID ? 'Imported GeoJSON building' : 'REST API feature',
        rows: Object.entries(feature.properties ?? {}).map(([label, value]) => ({
          label,
          value: value === null ? '—' : typeof value === 'object' ? JSON.stringify(value) : String(value),
        })),
      }
    },
    // Chỉ công bố ID lớp; Export query geometry đang render trên map, không lấy toàn collection.
    exportLayerIds: () =>
      geojson.state.enabled && geojson.state.collection.features.length ? [GEOJSON_IMPORT_ID] : [],
  }
}
