import center from '@turf/center'

export const TERRAIN_SOURCE_ID = 'city-terrain'
export const TILE_ZONE_SOURCE_ID = 'city-tile-zones'
export const TILE_ZONE_LABEL_SOURCE_ID = 'city-tile-zone-labels'
export const TILE_ZONE_FILL_ID = 'city-tile-zones-fill'

/**
 * Hai lựa chọn bổ sung cho HUD; một lựa chọn có thể quản lý nhiều layer.
 * Input UI: { contours: true, tileZones: false }.
 * Output: contour visible; cả fill/outline/label của vùng tiles đều none.
 * sourceIds dùng phân loại lỗi, không phải URL tải gói dữ liệu offline.
 */
export const mapOverlays = [
  {
    id: 'contours',
    label: 'Terrain contours',
    description: 'Elevation lines · Mapbox Terrain v2',
    sourceIds: [TERRAIN_SOURCE_ID],
    layerIds: ['city-terrain-contour'],
    defaultVisible: false,
  },
  {
    id: 'tileZones',
    label: 'Tile zones',
    description: '157 Montréal zones · Local grid',
    sourceIds: [TILE_ZONE_SOURCE_ID, TILE_ZONE_LABEL_SOURCE_ID],
    layerIds: [TILE_ZONE_FILL_ID, 'city-tile-zones-outline', 'city-tile-zones-label'],
    defaultVisible: false,
  },
]

/**
 * Gắn mã G(1)... và tạo điểm nhãn ở tâm bbox, giống cách code cũ dùng turf.center.
 *
 * @param {object} collection GeoJSON FeatureCollection polygon từ tileZones.json.
 * @returns {{polygons: object, labels: object}} Hai FeatureCollection dùng cho addSource.
 * Ví dụ input một polygon quanh [0,0]..[2,2] -> polygon có properties.zone="G(1)",
 * label Point tại [1,1]. Không sửa collection gốc; geometry được dùng lại chỉ để đọc.
 *
 * Dữ liệu cũ không chứa URL gói tiles. Không sao chép link Google placeholder
 * thành nút Download: click một vùng chỉ mở thông tin vùng đó.
 */
export function createTileZoneData(collection) {
  const polygons = {
    type: 'FeatureCollection',
    features: collection.features.map((feature, index) => ({
      ...feature,
      id: index + 1,
      properties: { ...feature.properties, zone: 'G(' + (index + 1) + ')' },
    })),
  }
  return {
    polygons,
    labels: {
      type: 'FeatureCollection',
      features: polygons.features.map((feature) => center(feature, { properties: feature.properties })),
    },
  }
}

/**
 * Thêm contour và vùng tiles khi style.load, trước khi thêm các building.
 *
 * @param {object} map Mapbox Map có style đã tải.
 * @param {Record<string, boolean>} visibility Ví dụ { contours: true, tileZones: false }.
 * @param {{polygons: object, labels: object}} zones Kết quả createTileZoneData().
 * @returns {void} Side effects: thêm source/layer chưa có rồi áp visibility.
 *
 * Contour dùng vector source-layer "contour"; không bật DEM, hillshade hay
 * làm thay đổi cao độ mặt nền. Vùng tiles dùng GeoJSON cục bộ, không tải gói offline.
 * Gọi lại không nhân đôi source/layer; lỗi tiles được chuyển tới useMapLayers.sourceError().
 */
export function addMapOverlays(map, visibility, zones) {
  for (const [id, source] of [
    [TERRAIN_SOURCE_ID, { type: 'vector', url: 'mapbox://mapbox.mapbox-terrain-v2' }],
    [TILE_ZONE_SOURCE_ID, { type: 'geojson', data: zones.polygons }],
    [TILE_ZONE_LABEL_SOURCE_ID, { type: 'geojson', data: zones.labels }],
  ]) {
    if (!map.getSource(id)) map.addSource(id, source)
  }
  const layers = [
    {
      id: 'city-terrain-contour',
      type: 'line',
      source: TERRAIN_SOURCE_ID,
      'source-layer': 'contour',
      layout: { 'line-join': 'round', 'line-cap': 'round' },
      paint: { 'line-color': '#aa9667', 'line-width': 2 },
    },
    {
      id: TILE_ZONE_FILL_ID,
      type: 'fill',
      source: TILE_ZONE_SOURCE_ID,
      paint: { 'fill-color': '#269cda', 'fill-opacity': 0.16 },
    },
    {
      id: 'city-tile-zones-outline',
      type: 'line',
      source: TILE_ZONE_SOURCE_ID,
      paint: { 'line-color': '#5db9ec', 'line-width': 1 },
    },
    {
      id: 'city-tile-zones-label',
      type: 'symbol',
      source: TILE_ZONE_LABEL_SOURCE_ID,
      layout: {
        'text-field': ['get', 'zone'],
        'text-font': ['Open Sans Regular', 'Arial Unicode MS Regular'],
        'text-size': 11,
      },
      paint: { 'text-color': '#ffc34d', 'text-halo-color': '#18212a', 'text-halo-width': 1.5 },
    },
  ]
  const ids = new Set(layers.map((layer) => layer.id))
  const basemap = map.getStyle().layers.filter((layer) => !ids.has(layer.id))
  const beforeId = basemap[basemap.findLastIndex((layer) => layer.type !== 'symbol') + 1]?.id
  for (const layer of layers) {
    if (!map.getLayer(layer.id)) {
      const entry = mapOverlays.find((overlay) => overlay.layerIds.includes(layer.id))
      map.addLayer(
        { ...layer, layout: { ...layer.layout, visibility: visibility[entry.id] === true ? 'visible' : 'none' } },
        beforeId,
      )
    }
  }
  setOverlayVisibility(map, visibility)
}

/**
 * @param {object} map Mapbox Map.
 * @param {Record<string, boolean>} visibility Ví dụ { tileZones: true }.
 * @returns {void} Bật cả ba layer vùng tiles; contours thiếu trong input được coi là tắt.
 * Chỉ đổi layout.visibility, không xóa nguồn/geometry. Bỏ qua layer chưa tồn tại
 * trong lúc đổi style; state Vue sẽ được áp lại ở style.load tiếp theo.
 */
export function setOverlayVisibility(map, visibility) {
  for (const entry of mapOverlays) {
    for (const id of entry.layerIds) {
      if (map.getLayer(id)) map.setLayoutProperty(id, 'visibility', visibility[entry.id] === true ? 'visible' : 'none')
    }
  }
}
