<script setup>
import { computed } from 'vue'
import CityHud from '../components/CityHud.vue'
import { sliceInfo } from './cfdData.js'
const props = defineProps({ cfd: { type: Object, required: true }, ready: Boolean })
const state = props.cfd.state
const slice = computed(() => (state.field ? sliceInfo(state.field, state.side) : { max: 50, spacing: 4 }))
</script>

<template>
  <!-- Bố cục: Chọn demo/file CFD và origin, sau đó điều khiển particles/lát cắt/contour; các tham số cập nhật cùng custom layer hiện có. -->
  <CityHud title="CFD settings">
    <div class="space-y-3">
      <VaButton size="small" :loading="state.loading" :disabled="!ready || state.loading" @click="cfd.load(null, true)"
        >Load CFD demo</VaButton
      >
      <VaFileUpload
        v-model="state.file"
        data-testid="cfd-file"
        type="single"
        upload-button-text="Local CFD file"
        file-types=".vtk,.dat,.txt"
        :disabled="state.loading"
        @update:modelValue="cfd.load($event)"
      />
      <VaFileUpload
        v-model="state.positionFile"
        data-testid="cfd-position"
        type="single"
        upload-button-text="Position settings"
        file-types=".txt,.json,.geojson"
        :disabled="state.loading"
        @update:modelValue="cfd.loadPosition($event)"
      />
      <VaProgressBar
        v-if="state.loading"
        :model-value="state.progress"
        :indeterminate="!state.progress"
        aria-label="Reading CFD field"
      />
      <div class="grid grid-cols-2 gap-2">
        <VaInput
          v-model="state.lng"
          type="number"
          label="Longitude"
          input-aria-label="Longitude"
          :disabled="state.loading"
        />
        <VaInput
          v-model="state.lat"
          type="number"
          label="Latitude"
          input-aria-label="Latitude"
          :disabled="state.loading"
        />
      </div>
      <VaButton size="small" preset="secondary" :disabled="!ready" @click="cfd.position()">Locate field</VaButton>
      <p class="text-xs text-secondary">
        Local format: ZONE I/J/K and x y z u v w rows. Origin is the horizontal center.
      </p>
      <template v-if="state.field">
        <p class="text-xs" data-testid="cfd-summary">
          {{ state.name }} · {{ state.field.width }} × {{ state.field.height }} × {{ state.field.depth }} nodes
        </p>
        <VaSwitch v-model="state.paused" label="Pause animation" aria-label="Pause CFD" size="small" />
        <VaSwitch v-model="state.slice" label="2D slice" aria-label="CFD 2D slice" size="small" />
        <VaSelect v-model="state.side" :options="['XY', 'YZ', 'XZ']" label="Slice plane" aria-label="CFD slice plane" />
        <VaSlider
          v-model="state.level"
          :min="0"
          :max="slice.max"
          :step="1"
          :label="'Level · ' + (state.level * slice.spacing).toFixed(2) + ' m'"
          aria-label="CFD level"
        />
        <VaSlider
          v-model="state.pointSize"
          :min="1"
          :max="20"
          :step="1"
          label="Particle size (px)"
          aria-label="CFD particle size"
        />
        <VaSlider v-model="state.speed" :min="0" :max="10" :step="0.1" label="Speed factor" aria-label="CFD speed" />
        <VaSwitch v-model="state.contours" label="Contour lines" aria-label="CFD contour lines" size="small" />
        <VaSlider
          v-if="state.contours"
          v-model="state.contourLevels"
          :min="1"
          :max="35"
          :step="1"
          label="Contour intervals"
          aria-label="CFD contour intervals"
        />
        <p class="text-xs">Field speed {{ state.field.min.toPrecision(4) }}–{{ state.field.max.toPrecision(4) }} m/s</p>
        <VaButton size="small" preset="secondary" @click="cfd.clear()">Clear CFD field</VaButton>
      </template>
      <VaAlert v-if="state.error" color="danger" dense outline class="mb-0 text-xs break-words">{{
        state.error
      }}</VaAlert>
    </div>
  </CityHud>
</template>
