import * as THREE from 'three'
import mapboxgl from 'mapbox-gl'
import { makeUnprojector } from '../../preprocessing/stl-converter/geojsonToStl.js'

/**
 * Input: STL X đông/Y lên/Z nam, snapshot origin/projection đã Apply.
 * Output: Float32Array cùng trục, mét render quanh origin; đổi từng đỉnh qua WGS84 để khớp Mapbox.
 * Giữ nguyên Y; Local/Web Mercator có tỉ lệ ngang khác nhau nên không dùng chung một scale cho dữ liệu thô.
 */
export function stlModelPositions(parsed, settings) {
  const origin = mapboxgl.MercatorCoordinate.fromLngLat([settings.lng, settings.lat])
  const unit = origin.meterInMercatorCoordinateUnits()
  const unproject = makeUnprojector([settings.lng, settings.lat], settings.projection ?? 'local')
  const positions = new Float32Array(parsed.triangleCount * 9)
  let offset = 0
  for (const solid of parsed.solids)
    for (let i = 0; i < solid.positions.length; i += 3) {
      const point = mapboxgl.MercatorCoordinate.fromLngLat(unproject([solid.positions[i], -solid.positions[i + 2]]))
      positions[offset++] = (point.x - origin.x) / unit
      positions[offset++] = solid.positions[i + 1]
      positions[offset++] = (point.y - origin.y) / unit
    }
  return positions
}

/**
 * Input: parsed STL (mét, X đông/Y lên/Z nam), getSettings() trả snapshot lng/lat/projection đã Apply.
 * Output: custom 3D layer đặc và wireframe như bản cũ. Đặt đúng origin STL tại lng/lat và giữ nguyên cao độ Y.
 * Không tự chạy animation: map vẽ khi di chuyển hoặc Apply. onRemove dispose toàn bộ GPU; parsed STL vẫn thuộc controller.
 */
export function createStlModelLayer(id, parsed, getSettings) {
  let renderer, scene, camera, geometry, material, wireMaterial, appliedSettings
  const local = new THREE.Matrix4(),
    projection = new THREE.Matrix4()
  const rotation = new THREE.Matrix4().makeRotationX(Math.PI / 2),
    scale = new THREE.Vector3()
  return {
    id,
    type: 'custom',
    renderingMode: '3d',
    onAdd(map, gl) {
      appliedSettings = getSettings()
      const positions = stlModelPositions(parsed, appliedSettings)
      geometry = new THREE.BufferGeometry()
      geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3))
      geometry.computeVertexNormals()
      scene = new THREE.Scene()
      camera = new THREE.Camera()
      const front = new THREE.DirectionalLight(0xffffff, 0.9),
        back = new THREE.DirectionalLight(0xffffff, 0.6)
      front.position.set(0, -70, 100).normalize()
      back.position.set(0, 70, 100).normalize()
      scene.add(front, back, new THREE.AmbientLight(0xffffff, 0.3))
      material = new THREE.MeshLambertMaterial({ color: 0x3f8cff, side: THREE.DoubleSide })
      wireMaterial = new THREE.MeshBasicMaterial({ color: 0x0b2a5c, wireframe: true })
      const mesh = new THREE.Mesh(geometry, material),
        wire = new THREE.Mesh(geometry, wireMaterial)
      mesh.frustumCulled = wire.frustumCulled = false
      scene.add(mesh, wire)
      renderer = new THREE.WebGLRenderer({ canvas: map.getCanvas(), context: gl, antialias: true })
      renderer.autoClear = false
    },
    render(gl, matrix) {
      const settings = getSettings(),
        origin = mapboxgl.MercatorCoordinate.fromLngLat([settings.lng, settings.lat])
      const unit = origin.meterInMercatorCoordinateUnits()
      // Chỉ chiếu lại khi Apply snapshot mới, không lặp công việc CPU mỗi frame.
      if (settings !== appliedSettings) {
        geometry.getAttribute('position').array.set(stlModelPositions(parsed, settings))
        geometry.getAttribute('position').needsUpdate = true
        geometry.computeVertexNormals()
        appliedSettings = settings
      }
      local
        .makeTranslation(origin.x, origin.y, origin.z)
        .scale(scale.set(unit, -unit, unit))
        .multiply(rotation)
      camera.projectionMatrix.copy(projection.fromArray(matrix)).multiply(local)
      renderer.resetState()
      // Mapbox sở hữu resize canvas; chỉ đồng bộ viewport, không gọi setSize làm đổi layout.
      renderer.setViewport(0, 0, gl.drawingBufferWidth, gl.drawingBufferHeight)
      renderer.render(scene, camera)
    },
    onRemove() {
      geometry?.dispose()
      material?.dispose()
      wireMaterial?.dispose()
      renderer?.dispose()
    },
  }
}
