import { getPosition } from 'suncalc'

/**
 * Đọc hai chuỗi từ picker Vuestic theo giờ địa phương của trình duyệt.
 *
 * @param {string} date YYYY-MM-DD, từ năm 1950.
 * @param {string} time HH:mm, ví dụ "09:30".
 * @returns {Date} Thời điểm hợp lệ trong múi giờ máy đang dùng.
 * @throws {RangeError} Nếu trống/sai định dạng, ngày không tồn tại hoặc giờ bị
 *   nhảy qua do DST. Không âm thầm đổi sang "bây giờ" khi input lỗi.
 *
 * Ví dụ "2026-06-21", "12:00" ở America/Toronto -> 2026-06-21T16:00:00.000Z.
 * Cùng input ở múi giờ khác là thời điểm UTC khác; HUD luôn ghi rõ múi giờ.
 */
export function parseShadingDate(date, time) {
  if (
    typeof date !== 'string' ||
    typeof time !== 'string' ||
    !/^\d{4}-\d{2}-\d{2}$/.test(date) ||
    !/^\d{2}:\d{2}$/.test(time)
  ) {
    throw new RangeError('Choose a valid local date and time.')
  }
  const [year, month, day] = date.split('-').map(Number)
  const [hour, minute] = time.split(':').map(Number)
  const value = new Date(date + 'T' + time + ':00')
  if (
    year < 1950 ||
    !Number.isFinite(value.getTime()) ||
    value.getFullYear() !== year ||
    value.getMonth() + 1 !== month ||
    value.getDate() !== day ||
    value.getHours() !== hour ||
    value.getMinutes() !== minute
  ) {
    throw new RangeError('Choose a valid local date and time (1950 or later).')
  }
  return value
}

/**
 * Tính mặt trời rồi tạo ánh sáng/bóng đổ bằng API công khai của Mapbox 3.
 *
 * @param {{date: string, time: string, sunlight: boolean}} params Input từ HUD.
 * @param {{lng: number, lat: number}} location Tâm bản đồ, độ theo WGS84.
 * @returns {{position: object, lights: object[]}} position có altitude/azimuth theo ĐỘ;
 *   lights gồm ambient + directional, dùng trực tiếp cho map.setLights().
 *
 * SunCalc 2.x: azimuth quay theo chiều kim đồng hồ từ Bắc, altitude là góc
 * trên chân trời, đều dùng độ. KHÔNG cộng 180 hoặc đổi radian như SunCalc 1.x.
 * Mapbox direction=[azimuth, polar]; polar=90-altitude. Khi mặt trời dưới chân
 * trời, tắt cast-shadows và directional intensity; ánh sáng ambient vẫn còn.
 *
 * Ví dụ altitude=30, azimuth=120 -> direction=[120,60], cast-shadows=true.
 * Sunrise cực thấp được chặn polar ở 89.5 độ để không tạo bóng gần vô hạn.
 * sunlight=false dùng sáng trắng; true dùng màu HSL theo công thức code cũ
 * nhưng lightness được chặn 0..100. Đây là hình ảnh minh họa, không tính bức xạ.
 *
 * Tham chiếu:
 * https://github.com/mourner/suncalc/releases/tag/v2.0.0
 * https://docs.mapbox.com/style-spec/reference/light/
 */
export function getShadingLighting(params, location) {
  if (!Number.isFinite(location?.lat) || !Number.isFinite(location?.lng) || Math.abs(location.lat) > 90) {
    throw new RangeError('The map location is not valid.')
  }
  const date = parseShadingDate(params.date, params.time)
  const position = getPosition(date, location.lat, location.lng)
  const { altitude, azimuth } = position
  if (!Number.isFinite(altitude) || !Number.isFinite(azimuth)) {
    throw new RangeError('Could not calculate the sun position.')
  }
  const day = altitude > 0
  const radians = (altitude * Math.PI) / 180
  const lightness = Math.max(0, Math.min(100, 200 * Math.sin(radians))).toFixed(2)
  const saturation = (50 * Math.cos(radians)).toFixed(2)
  return {
    position,
    lights: [
      {
        id: 'city-ambient',
        type: 'ambient',
        properties: { color: '#ffffff', intensity: params.sunlight ? (day ? 0.2 : 0.15) : 0.3 },
      },
      {
        id: 'city-sun',
        type: 'directional',
        properties: {
          direction: [((azimuth % 360) + 360) % 360, 90 - Math.max(0.5, Math.min(90, altitude))],
          'direction-transition': { duration: 0 },
          color: params.sunlight ? 'hsl(20, ' + saturation + '%, ' + lightness + '%)' : '#ffffff',
          'color-transition': { duration: 0 },
          intensity: day ? 1 : 0,
          'intensity-transition': { duration: 0 },
          'cast-shadows': day,
          // Giữ độ đậm ổn định ban ngày; sin(altitude) trước đây làm bóng quá nhạt khi mặt trời thấp.
          'shadow-intensity': day ? 0.95 : 0,
        },
      },
    ],
  }
}

/**
 * Giữ màu/độ sáng các bề mặt 2D khi bật ánh sáng 3D để vẽ bóng.
 *
 * @param {object} map Mapbox Map đã sẵn sàng style và các layer của City.
 * @returns {Array<[string, string, unknown]>} Các [layerId, property, giá trị gốc]
 *   để cityMap khôi phục khi tắt Shading. null nghĩa là property chưa được cấu hình.
 *
 * Ví dụ background-emissive-strength=0 -> lưu 0, đặt 1: nền giữ màu style dù
 * ambient/sun đổi theo giờ. Transition đặt 0 để không tối thoáng qua khi bật.
 * Bóng vẫn do shadow pass của Mapbox vẽ; không sửa màu, opacity hay geometry nhà.
 * Không áp emissive lên fill-extrusion/model: nhà 3D vẫn nhận sáng và tạo bóng.
 * Chỉ gọi một lần khi chuyển từ tắt sang bật, không ghi đè snapshot khi đổi giờ.
 */
export function preserveMapBrightness(map) {
  const properties = {
    background: ['background-emissive-strength'],
    fill: ['fill-emissive-strength'],
    line: ['line-emissive-strength'],
    circle: ['circle-emissive-strength'],
    symbol: ['text-emissive-strength', 'icon-emissive-strength'],
    raster: ['raster-emissive-strength'],
    hillshade: ['hillshade-emissive-strength'],
  }
  const original = []
  for (const { id, type } of map.getStyle().layers) {
    for (const property of properties[type] || []) {
      for (const [name, value] of [
        [property + '-transition', { duration: 0 }],
        [property, 1],
      ]) {
        original.push([id, name, map.getPaintProperty(id, name) ?? null])
        map.setPaintProperty(id, name, value)
      }
    }
  }
  return original
}
