import { markRaw, onBeforeUnmount, reactive, watch } from 'vue'
import { parseSTL } from '../../preprocessing/stl-converter/stlio.js'
import { importPosition, stlPosition } from './importData.js'
import { createStlModelLayer } from './stlModelLayer.js'

/** Input: getMap/ready. Output: nhiều STL với draft tọa độ riêng; Apply mới thay snapshot bản đồ/Export.
 * ASCII/binary dùng parser đã có; mỗi file lỗi riêng. Tắt nhóm dispose GPU nhưng giữ parsed STL để bật/restore mà không đọc lại.
 */
export function useStlImport({ getMap, ready }) {
  const state = reactive({ enabled: false, files: [], models: [], loading: false })
  const layers = new Set()
  let nextId = 0,
    request = 0,
    disposed = false
  function sync() {
    const map = getMap()
    if (!map || !ready.value || disposed) return
    for (const id of layers)
      if (!state.enabled || !state.models.some((model) => model.id === id && model.applied)) {
        if (map.getLayer(id)) map.removeLayer(id)
        layers.delete(id)
      }
    for (const model of state.models) {
      if (!state.enabled || !model.applied || map.getLayer(model.id)) continue
      const layer = createStlModelLayer(model.id, model.parsed, () => model.applied)
      try {
        map.addLayer(layer)
        layers.add(model.id)
      } catch {
        if (map.getLayer(model.id)) map.removeLayer(model.id)
        else layer.onRemove()
        model.error = 'Could not render this STL model.'
      }
    }
    map.triggerRepaint()
  }
  async function load(input) {
    const current = ++request,
      files = input ? (Array.isArray(input) ? input : [input]) : []
    const previous = state.models,
      models = []
    state.loading = true
    for (const file of files) {
      const existing = previous.find((model) => model.file === file)
      if (existing) {
        models.push(existing)
        continue
      }
      const location = getMap()?.getCenter() ?? { lng: -73.57825, lat: 45.49556 }
      const model = {
        id: 'city-import-stl-' + ++nextId,
        file: markRaw(file),
        name: file.name,
        lng: location.lng,
        lat: location.lat,
        projection: 'local',
        positionFile: [],
        positionRequest: 0,
        positionLoading: false,
        parsed: null,
        applied: null,
        error: '',
      }
      try {
        // shortcut: đọc trên main thread, giới hạn 100MB/2 triệu triangle; chuyển worker khi cần STL lớn hơn.
        if (file.size > 100 * 1024 * 1024) throw new Error('STL files must be at most 100 MB.')
        const parsed = parseSTL(await file.arrayBuffer(), file.name.replace(/\.[^.]+$/, ''))
        if (parsed.triangleCount > 2000000) throw new Error('STL must contain at most 2 million triangles.')
        model.parsed = markRaw(parsed)
      } catch (error) {
        model.error = error.message
      }
      if (disposed || current !== request) return
      models.push(model)
    }
    if (!disposed && current === request) {
      state.models = models
      state.loading = false
      sync()
    }
  }
  /** File kèm chỉ điền draft origin/projection; Apply mới thay vị trí trên map. */
  async function loadPosition(model, input) {
    const file = Array.isArray(input) ? input[0] : input
    const current = ++model.positionRequest
    if (!file) {
      model.positionLoading = false
      return
    }
    model.positionLoading = true
    model.error = ''
    try {
      if (file.size > 65536) throw new Error('Position files must be at most 64 KB.')
      const { origin, projection } = stlPosition(await file.text())
      if (disposed || !state.models.includes(model) || current !== model.positionRequest) return
      Object.assign(model, { lng: origin[0], lat: origin[1], projection })
    } catch (error) {
      if (!disposed && state.models.includes(model) && current === model.positionRequest) model.error = error.message
    } finally {
      if (current === model.positionRequest) model.positionLoading = false
    }
  }
  function apply(model, fly = false) {
    model.error = ''
    try {
      if (!ready.value || !model.parsed) throw new Error('Load a valid STL and wait for the map first.')
      const [lng, lat] = importPosition(model.lng, model.lat)
      if (!['local', 'web-mercator'].includes(model.projection)) throw new Error('Unsupported STL projection.')
      model.applied = markRaw({
        name: model.name,
        parsed: model.parsed,
        lng,
        lat,
        projection: model.projection,
      })
      sync()
      if (fly) getMap()?.flyTo({ center: [lng, lat], zoom: 16, pitch: 55 })
    } catch (error) {
      model.error = error.message
    }
  }
  function remove(model) {
    request++
    state.loading = false
    state.models = state.models.filter((item) => item !== model)
    state.files = state.files.filter((file) => file !== model.file)
    sync()
  }
  function restore() {
    layers.clear()
    sync()
  }
  watch(() => state.enabled, sync)
  onBeforeUnmount(() => {
    request++
    disposed = true
    const map = getMap()
    for (const id of layers) if (map?.getLayer(id)) map.removeLayer(id)
    layers.clear()
  })
  return {
    state,
    load,
    apply,
    loadPosition,
    remove,
    restore,
    exportModels: () =>
      state.enabled ? state.models.filter((model) => model.applied).map((model) => model.applied) : [],
  }
}
