<script setup>
import CityHud from '../components/CityHud.vue'
const props = defineProps({ controller: { type: Object, required: true }, ready: Boolean })
const state = props.controller.state
</script>

<template>
  <!-- Mỗi URL có JSON tree và mapping riêng; chọn path thêm point/feature, Show/Monitor cập nhật snapshot thay vì nối trùng. -->
  <CityHud title="REST API import settings">
    <VaButton size="small" @click="controller.addLink()">Add API link</VaButton>
    <VaForm
      v-for="(link, index) in state.links"
      :key="link.id"
      novalidate
      class="space-y-3"
      @submit.prevent="controller.load(link)"
    >
      <VaDivider />
      <div class="flex items-center justify-between gap-2">
        <h3 class="text-xs font-semibold">API {{ index + 1 }}</h3>
        <VaButton
          size="small"
          preset="plain"
          icon="ion-md-close"
          :aria-label="'Remove API ' + (index + 1)"
          @click="controller.removeLink(link)"
        />
      </div>
      <VaInput
        v-model="link.url"
        label="URL"
        :input-aria-label="'API ' + (index + 1) + ' URL'"
        :disabled="link.monitoring || link.loading"
      />
      <VaButton size="small" type="submit" :loading="link.loading" :disabled="link.monitoring || link.loading"
        >Load response</VaButton
      >
      <template v-if="link.data !== null">
        <VaCollapse header="JSON response" stateful>
          <template #body><VaTreeView :nodes="link.tree" class="min-w-0 break-all" /></template>
        </VaCollapse>
        <VaSwitch v-model="link.geojsonMode" label="GeoJSON features" size="small" />
        <VaSelect
          v-if="link.geojsonMode"
          v-model="link.featurePath"
          :options="link.options"
          text-by="label"
          value-by="id"
          searchable
          label="GeoJSON field"
          aria-label="API GeoJSON field"
        />
        <template v-else>
          <VaSelect
            v-model="link.latPath"
            :options="link.options"
            text-by="label"
            value-by="id"
            searchable
            label="Latitude field"
            aria-label="API latitude field"
          />
          <VaSelect
            v-model="link.lngPath"
            :options="link.options"
            text-by="label"
            value-by="id"
            searchable
            label="Longitude field"
            aria-label="API longitude field"
          />
          <VaSelect
            v-model="link.valuePath"
            :options="link.options"
            text-by="label"
            value-by="id"
            searchable
            label="Value field"
            aria-label="API value field"
          />
        </template>
        <VaButton size="small" preset="secondary" @click="controller.addSelection(link)">{{
          link.geojsonMode ? 'Add feature selection' : 'Add point selection'
        }}</VaButton>
      </template>
      <div v-for="(selection, no) in link.selections" :key="selection.id" class="space-y-2">
        <p class="text-xs">Selection {{ no + 1 }} · {{ selection.kind }}</p>
        <div v-if="selection.kind === 'point'" class="grid grid-cols-2 gap-2">
          <VaInput v-model="selection.lat" label="Latitude" input-aria-label="Selected point latitude" />
          <VaInput v-model="selection.lng" label="Longitude" input-aria-label="Selected point longitude" />
          <VaInput v-model="selection.value" label="Value" input-aria-label="Selected point value" />
        </div>
        <VaButton size="small" preset="secondary" @click="controller.removeSelection(link, selection)"
          >Remove selection</VaButton
        >
      </div>
      <p v-if="link.applied" class="text-xs" data-testid="import-rest-summary">
        {{ link.applied.features.length }} API features displayed
      </p>
      <VaInput
        v-model="link.interval"
        type="number"
        label="Update interval (seconds)"
        input-aria-label="API update interval"
        :disabled="link.monitoring"
      />
      <p class="text-xs text-secondary">0: once · 10–3600: repeat. Refresh reads the selected JSON fields again.</p>
      <div class="flex flex-wrap gap-2">
        <VaButton size="small" :disabled="!ready || !link.selections.length" @click="controller.apply(link)"
          >Show on map</VaButton
        >
        <VaButton
          v-if="!link.monitoring"
          size="small"
          :disabled="!ready || link.loading"
          @click="controller.start(link)"
          >Monitor API</VaButton
        >
        <VaButton v-else size="small" @click="controller.stop(link)">Stop monitoring</VaButton>
        <VaButton size="small" preset="secondary" @click="controller.clear(link)">Clear selection</VaButton>
      </div>
      <VaAlert v-if="link.error" color="danger" dense outline class="mb-0 text-xs break-words">{{
        link.error
      }}</VaAlert>
    </VaForm>
    <VaAlert v-if="state.error" color="danger" dense outline class="mb-0 text-xs break-words">{{
      state.error
    }}</VaAlert>
  </CityHud>
</template>
