import { computed, reactive, watch } from 'vue'
import { addBuildingLayers, buildingLayers, CONCORDIA_SOURCE_ID, setBuildingVisibility } from './buildingLayers.js'
import { addMapOverlays, createTileZoneData, mapOverlays, setOverlayVisibility } from './terrainTileLayers.js'
import tileZones from './tileZones.json'
import { useShading } from './useShading.js'

const zoneData = createTileZoneData(tileZones)

/**
 * Input: getMap() và ready ref của cùng Mapbox City. Output: state riêng cho LayerHud + controller Shading.
 * Ví dụ layerVisibility['city-concordia-2d']=true -> chỉ đổi visibility lớp 2D; lựa chọn 3D giữ nguyên.
 * restore() dựng source/layer khi style.load; sourceError(sourceId) chỉ ghi lỗi đúng nhóm nguồn và trả true nếu đã xử lý.
 */
export function useMapLayers({ getMap, ready, importer }) {
  const layerVisibility = reactive(Object.fromEntries(buildingLayers.map((entry) => [entry.id, entry.defaultVisible])))
  const layerErrors = reactive({})
  const overlayVisibility = reactive(Object.fromEntries(mapOverlays.map((entry) => [entry.id, entry.defaultVisible])))
  const overlayErrors = reactive({})

  const shadingControls = useShading({ getMap, ready, layerVisibility, layerErrors, importer })
  const enabledLayerCount = computed(
    () =>
      Object.values(layerVisibility).filter(Boolean).length +
      Object.values(overlayVisibility).filter(Boolean).length +
      Number(shadingControls.shading.enabled),
  )
  const layerErrorMessages = computed(() => [...new Set(Object.values(layerErrors))])

  watch(layerVisibility, () => {
    const map = getMap()
    if (map && ready.value) setBuildingVisibility(map, layerVisibility)
  })
  watch(overlayVisibility, () => {
    const map = getMap()
    if (map && ready.value) setOverlayVisibility(map, overlayVisibility)
  })

  function restore() {
    const map = getMap()
    try {
      addMapOverlays(map, overlayVisibility, zoneData)
      Object.assign(layerErrors, addBuildingLayers(map, layerVisibility))
    } finally {
      shadingControls.resetStyle()
    }
  }

  function clearErrors() {
    for (const id of Object.keys(layerErrors)) delete layerErrors[id]
    for (const id of Object.keys(overlayErrors)) delete overlayErrors[id]
  }

  /** sourceId từ Mapbox -> lỗi HUD; không đưa URL/token thô ra giao diện. */
  function sourceError(sourceId) {
    if (sourceId === CONCORDIA_SOURCE_ID) {
      const message = 'Concordia data could not be loaded. Check access to this dataset.'
      for (const entry of buildingLayers) {
        if (entry.layer.source === CONCORDIA_SOURCE_ID) layerErrors[entry.id] = message
      }
      return true
    }
    const overlay = mapOverlays.find((entry) => entry.sourceIds.includes(sourceId))
    if (!overlay) return false
    overlayErrors[overlay.id] = 'Could not load ' + overlay.label.toLowerCase() + '. Check source access.'
    return true
  }

  return {
    ready,
    buildingLayers,
    layerVisibility,
    layerErrors,
    layerErrorMessages,
    mapOverlays,
    overlayVisibility,
    overlayErrors,
    shadingControls,
    enabledLayerCount,
    restore,
    clearErrors,
    sourceError,
  }
}
