import { nextTick, onBeforeUnmount, ref, watch } from 'vue'
import mapboxgl from 'mapbox-gl'
import { buildingLayers } from './buildingLayers.js'
import { TILE_ZONE_FILL_ID } from './terrainTileLayers.js'
import { getBuildingDetails } from './buildingDetails.js'

/**
 * Input: getMap/ready, hai bảng visibility và handlesClick() của Export để tránh bắt click khi đang vẽ vùng.
 * Output: DOM ref popupElement, selectedFeature chứa các hàng text, closeFeature() và attach() gắn sự kiện map.
 * Click building -> getBuildingDetails(properties); tile zone -> thông tin vùng; importer cung cấp layer IDs và popup properties của GeoJSON/REST.
 * Click trống/di chuyển/tắt lớp đóng popup. Hủy route vô hiệu hóa click đang chờ Vue nextTick và tháo listener.
 */
export function useLayerDetails({ getMap, ready, layerVisibility, overlayVisibility, handlesClick, importer }) {
  const popupElement = ref(null)
  const selectedFeature = ref(null)
  let popup,
    disposed = false

  /** Output: đóng popup và xóa lựa chọn; gọi khi click trống, Escape hoặc đổi style. */
  function closeFeature() {
    selectedFeature.value = null
    popup?.remove()
  }

  /** Input: điểm pixel từ click/mousemove. Output: building ưu tiên trước vùng tiles. */
  function featureAt(point) {
    const map = getMap()
    if (!map || !ready.value) return null
    const ids = [...buildingLayers.map((entry) => entry.id), ...importer.interactiveLayers(), TILE_ZONE_FILL_ID].filter(
      (id) => map.getLayer(id),
    )
    const features = map.queryRenderedFeatures(point, { layers: ids })
    return features.find((feature) => feature.layer.id !== TILE_ZONE_FILL_ID) || features[0] || null
  }

  async function onClick(event) {
    const map = getMap()
    if (handlesClick()) return
    const feature = featureAt(event.point)
    closeFeature()
    if (!feature) return
    const building = buildingLayers.find((entry) => entry.id === feature.layer.id)
    selectedFeature.value = building
      ? {
          kind: 'building',
          layerId: building.id,
          title: building.label,
          rows: getBuildingDetails(feature.properties),
        }
      : feature.layer.id === TILE_ZONE_FILL_ID
        ? {
            kind: 'zone',
            title: 'Zone ' + feature.properties.zone,
            rows: [
              { label: 'Grid', value: 'Montréal' },
              { label: 'Tile package', value: 'Unavailable' },
            ],
          }
        : importer.featureDetails(feature)
    const selection = selectedFeature.value
    await nextTick()
    // Bỏ click cũ nếu route đã đóng hoặc có click mới trong lúc Vue cập nhật DOM.
    if (disposed || getMap() !== map || selectedFeature.value !== selection) return
    popup.setDOMContent(popupElement.value).setLngLat(event.lngLat).addTo(map)
  }

  function onMouseMove(event) {
    const map = getMap()
    if (handlesClick()) {
      map.getCanvas().style.cursor = 'crosshair'
      return
    }
    map.getCanvas().style.cursor = featureAt(event.point) ? 'pointer' : ''
  }

  function onClose() {
    selectedFeature.value = null
  }

  /** Owner gọi một lần sau new Mapbox.Map; Vue giữ nội dung text, Mapbox chỉ định vị popup. */
  function attach() {
    const map = getMap()
    popup = new mapboxgl.Popup({ closeButton: false, closeOnClick: false, maxWidth: '320px', focusAfterOpen: false })
    popup.on('close', onClose)
    map.on('click', onClick)
    map.on('mousemove', onMouseMove)
    map.on('movestart', closeFeature)
  }

  watch(layerVisibility, () => {
    if (selectedFeature.value?.kind === 'building' && !layerVisibility[selectedFeature.value.layerId]) closeFeature()
  })
  watch(overlayVisibility, () => {
    if (selectedFeature.value?.kind === 'zone' && !overlayVisibility.tileZones) closeFeature()
  })
  watch(
    () => [
      importer.geojson.state.enabled,
      importer.geojson.state.collection,
      importer.rest.state.enabled,
      ...importer.rest.state.links.map((link) => link.applied),
    ],
    () => {
      if (selectedFeature.value?.kind === 'imported') closeFeature()
    },
  )
  onBeforeUnmount(() => {
    disposed = true
    const map = getMap()
    map?.off('click', onClick)
    map?.off('mousemove', onMouseMove)
    map?.off('movestart', closeFeature)
    popup?.off('close', onClose)
    closeFeature()
    popup = null
  })

  return { popupElement, selectedFeature, closeFeature, attach }
}
