import { markRaw, onBeforeUnmount, reactive, watch } from 'vue'
import { numeric } from '../visualize/csvBesData.js'
import { jsonFields, jsonValue, restFeatures, restPoint, restUrl, REST_IMPORT_ID } from './importData.js'

/**
 * Input: getMap/ready. Output: nhiều URL độc lập, JSON tree/path, các point/feature đã chọn và snapshot bản đồ.
 * Ví dụ /station/lat, /station/lng, /station/temp -> Point có properties.value; /features/0 -> GeoJSON đã validate.
 * Mỗi link thay snapshot của chính nó khi refresh, không append trùng. Monitor chạy sau mỗi request xong; tắt/xóa/rời route hủy request/timer.
 */
export function useRestApiImport({ getMap, ready }) {
  const state = reactive({ enabled: false, links: [], error: '' })
  const requests = new Map(),
    timers = new Map()
  let nextId = 0,
    nextSelection = 0,
    disposed = false
  function addLink() {
    state.links.push({
      id: ++nextId,
      url: '',
      loading: false,
      error: '',
      data: null,
      tree: [],
      options: [],
      geojsonMode: false,
      latPath: null,
      lngPath: null,
      valuePath: null,
      featurePath: '',
      // selections là form/mapping; applied là snapshot đang vẽ, refresh đọc lại các JSON path.
      selections: [],
      applied: null,
      interval: 0,
      monitoring: false,
      run: 0,
    })
  }
  addLink()
  function sync() {
    const map = getMap()
    if (!map || !ready.value || disposed) return
    const collection = {
      type: 'FeatureCollection',
      features: state.links.flatMap((link) => link.applied?.features ?? []),
    }
    if (collection.features.length && !map.getSource(REST_IMPORT_ID))
      map.addSource(REST_IMPORT_ID, { type: 'geojson', data: collection })
    else map.getSource(REST_IMPORT_ID)?.setData(collection)
    if (!map.getSource(REST_IMPORT_ID)) return
    for (const [suffix, type, geometry, paint] of [
      ['polygons', 'fill', 'Polygon', { 'fill-color': '#0080ff', 'fill-opacity': 0.5, 'fill-emissive-strength': 1 }],
      ['lines', 'line', 'LineString', { 'line-color': '#0080ff', 'line-width': 3, 'line-emissive-strength': 1 }],
      [
        'points',
        'circle',
        'Point',
        {
          'circle-color': '#0080ff',
          'circle-radius': 7,
          'circle-stroke-width': 1,
          'circle-stroke-color': '#ffffff',
          'circle-emissive-strength': 1,
        },
      ],
    ]) {
      const id = REST_IMPORT_ID + '-' + suffix
      if (!map.getLayer(id))
        map.addLayer({ id, source: REST_IMPORT_ID, type, filter: ['==', ['geometry-type'], geometry], paint })
      map.setLayoutProperty(id, 'visibility', state.enabled && collection.features.length ? 'visible' : 'none')
    }
  }
  function resolveSelection(selection, data) {
    return selection.kind === 'point'
      ? {
          ...selection,
          lat: jsonValue(data, selection.latPath),
          lng: jsonValue(data, selection.lngPath),
          value: jsonValue(data, selection.valuePath),
        }
      : { ...selection, features: markRaw(restFeatures(jsonValue(data, selection.featurePath))) }
  }
  function selectionCollection(selections) {
    const features = selections.flatMap((s) => (s.kind === 'point' ? [restPoint(s.lat, s.lng, s.value)] : s.features))
    if (!features.length) throw new Error('Add at least one point or GeoJSON selection.')
    return { type: 'FeatureCollection', features }
  }
  function apply(link) {
    link.error = ''
    try {
      link.applied = markRaw(selectionCollection(link.selections))
      sync()
    } catch (error) {
      link.error = error.message
    }
  }
  function addSelection(link) {
    link.error = ''
    try {
      if (link.data === null) throw new Error('Load a JSON response first.')
      const selected = resolveSelection(
        {
          id: ++nextSelection,
          kind: link.geojsonMode ? 'feature' : 'point',
          latPath: link.latPath,
          lngPath: link.lngPath,
          valuePath: link.valuePath,
          featurePath: link.featurePath,
        },
        link.data,
      )
      selectionCollection([selected])
      link.selections.push(selected)
    } catch (error) {
      link.error = error.message
    }
  }
  function removeSelection(link, selection) {
    link.selections = link.selections.filter((item) => item.id !== selection.id)
    if (link.applied) {
      if (link.selections.length) apply(link)
      else {
        link.applied = null
        sync()
      }
    }
  }
  async function load(link) {
    requests.get(link.id)?.abort()
    const controller = new AbortController()
    requests.set(link.id, controller)
    link.loading = true
    link.error = ''
    try {
      const response = await fetch(restUrl(link.url), { signal: controller.signal, credentials: 'omit' })
      if (!response.ok) throw new Error('API request failed (HTTP ' + response.status + ').')
      let data
      try {
        data = await response.json()
      } catch {
        throw new Error('Response is not valid JSON.')
      }
      controller.signal.throwIfAborted()
      if (disposed || requests.get(link.id) !== controller) return
      if (data === null || typeof data !== 'object') throw new Error('API response must be a JSON object or array.')
      const fields = jsonFields(data),
        selections = link.selections.map((s) => resolveSelection(s, data))
      const applied = selections.length ? selectionCollection(selections) : null
      link.data = markRaw(data)
      link.tree = markRaw(fields.tree)
      link.options = markRaw(fields.options)
      link.selections = selections
      if (applied) {
        link.applied = markRaw(applied)
        sync()
      }
    } catch (error) {
      if (!controller.signal.aborted && !disposed)
        link.error =
          error instanceof TypeError ? 'Could not load JSON. Check the URL, CORS and network.' : error.message
    } finally {
      if (requests.get(link.id) === controller) {
        requests.delete(link.id)
        link.loading = false
      }
    }
  }
  function stop(link) {
    link.run = (link.run ?? 0) + 1
    link.monitoring = false
    link.loading = false
    clearTimeout(timers.get(link.id))
    timers.delete(link.id)
    requests.get(link.id)?.abort()
    requests.delete(link.id)
  }
  async function start(link) {
    stop(link)
    const seconds = numeric(link.interval)
    if (!Number.isInteger(seconds) || seconds < 0 || seconds > 3600 || (seconds > 0 && seconds < 10)) {
      link.error = 'Update interval must be 0 (once), or 10–3600 seconds.'
      return
    }
    if (!link.selections.length) {
      link.error = 'Add a point or GeoJSON selection first.'
      return
    }
    link.monitoring = true
    const run = link.run
    async function tick() {
      if (disposed || !state.enabled || !link.monitoring || run !== link.run) return
      await load(link)
      if (disposed || !state.enabled || !link.monitoring || run !== link.run) return
      if (seconds) timers.set(link.id, setTimeout(tick, seconds * 1000))
      else link.monitoring = false
    }
    await tick()
  }
  function removeLink(link) {
    stop(link)
    state.links = state.links.filter((item) => item.id !== link.id)
    sync()
  }
  function clear(link) {
    stop(link)
    link.selections = []
    link.applied = null
    link.error = ''
    sync()
  }
  function restore() {
    try {
      sync()
    } catch {
      state.error = 'Could not display imported REST data for this basemap.'
    }
  }
  watch(
    () => state.enabled,
    (enabled) => {
      if (!enabled) state.links.forEach(stop)
      restore()
    },
  )
  onBeforeUnmount(() => {
    disposed = true
    state.links.forEach(stop)
  })
  return { state, addLink, removeLink, load, addSelection, removeSelection, apply, start, stop, clear, restore }
}
