import { markRaw, onBeforeUnmount, reactive, watch } from 'vue'
import { buildingLayers } from '../layer/buildingLayers.js'
import {
  bemValues,
  csvOverlay,
  csvValues,
  joinKey,
  matchColors,
  numeric,
  parseCsv,
  propertyNames,
  readBem,
  readPolygons,
  scalarStyle,
  valuePolygons,
} from './csvBesData.js'

/**
 * Input: getMap/ready và bảng visibility building. Output: bốn entry CSV/GeoJSON, CSV 2D/3D và BES/BEM.
 * load(entry, 'csv'|'geo'|'data', File) -> parse có hủy/race guard; apply(entry) -> snapshot màu và source/paint.
 * Ví dụ CSV id=123/value=28 -> tô feature nd='123'. Cùng lớp building: entry Apply mới nhất đang bật thắng.
 * Các mode dùng chung quy trình màu/snapshot; CFD có controller và vòng đời GPU riêng.
 */
export function useCsvBesVisualization({ getMap, ready, layerVisibility }) {
  const entries = reactive(
    [
      { id: 'csv-geojson', label: 'CSV / GeoJSON', target: 'geojson' },
      { id: 'csv-2d', label: 'CSV → Concordia 2D', target: 'city-concordia-2d' },
      { id: 'csv-3d', label: 'CSV → Concordia 3D', target: 'city-concordia-3d' },
      { id: 'bem', label: 'BES / BEM', target: 'city-concordia-2d' },
    ].map((entry) => ({
      ...entry,
      enabled: false,
      geoFile: [],
      csvFile: [],
      dataFile: [],
      loading: false,
      progress: 0,
      error: '',
      csv: null,
      geo: null,
      data: null,
      csvKey: '',
      geoKey: '',
      valueKey: '',
      variable: 0,
      timestep: 0,
      external: false,
      min: '',
      max: '',
      palette: 'Oranges',
      steps: 4,
      applied: null,
    })),
  )

  // Theo ID để thêm/đổi thứ tự menu không làm watcher theo nhầm entry.
  const bem = entries.find((entry) => entry.id === 'bem')
  const requests = new Map(),
    sourceData = new Map()
  let sequence = 0,
    disposed = false

  /** Chỉ ghi state khi lượt đọc vẫn là lượt hiện tại; file cũ hoàn tất muộn không được ghi đè lựa chọn mới. */
  async function load(entry, kind, input) {
    const file = Array.isArray(input) ? input[0] : input
    requests.get(entry.id)?.abort()
    const controller = new AbortController()
    requests.set(entry.id, controller)
    entry.error = ''
    entry.loading = Boolean(file)
    entry.progress = 0
    entry[kind] = null
    if (!file) {
      requests.delete(entry.id)
      return
    }
    try {
      const options = {
        signal: controller.signal,
        onProgress: (value) => {
          if (!controller.signal.aborted) entry.progress = value
        },
      }
      let result
      if (kind === 'csv') result = await parseCsv(await file.text())
      else if (kind === 'geo') result = readPolygons(await file.text())
      else result = await readBem(file, options)
      controller.signal.throwIfAborted()
      if (disposed) return
      entry[kind] = markRaw(result)
      if (kind === 'csv') {
        entry.csvKey =
          result.headers.find((name) => /^(nd|id|osm_id|building_osm_id)$/i.test(name)) ?? result.headers[0]
        entry.valueKey =
          result.headers.find(
            (name, index) => name !== entry.csvKey && result.rows.some((row) => numeric(row[index]) !== null),
          ) ?? ''
      } else if (kind === 'geo') {
        entry.geoKey =
          propertyNames(result).find((name) => /^(nd|id|osm_id)$/i.test(name)) ?? propertyNames(result)[0] ?? ''
        if (!entry.csv)
          entry.valueKey =
            propertyNames(result).find(
              (name) =>
                name !== entry.geoKey &&
                name !== 'auto_id' &&
                result.features.some((feature) => numeric(feature.properties?.[name]) !== null),
            ) ?? ''
      } else {
        entry.variable = 0
        entry.timestep = 0
      }
    } catch (error) {
      if (!controller.signal.aborted && !disposed)
        entry.error =
          'Could not read ' + (kind === 'data' ? 'BES' : kind === 'geo' ? 'GeoJSON' : 'CSV') + ': ' + error.message
    } finally {
      if (requests.get(entry.id) === controller) {
        entry.loading = false
        requests.delete(entry.id)
      }
    }
  }

  function overlayId(entry) {
    return 'city-viz-' + entry.id
  }

  /** Tạo/khôi phục nguồn GeoJSON và paint building. Cùng target: lần Apply mới nhất đang bật có ưu tiên. */
  function sync() {
    const map = getMap()
    if (!map || !ready.value || disposed) return
    for (const entry of entries) {
      const id = overlayId(entry),
        applied = entry.applied
      if (applied?.collection) {
        if (!map.getSource(id)) map.addSource(id, { type: 'geojson', data: applied.collection })
        else if (sourceData.get(id) !== applied.collection) map.getSource(id).setData(applied.collection)
        sourceData.set(id, applied.collection)
        if (!map.getLayer(id))
          map.addLayer({
            id,
            type: 'fill',
            source: id,
            paint: { 'fill-opacity': 0.75, 'fill-emissive-strength': 1, 'fill-color': applied.expression },
          })
        map.setPaintProperty(id, 'fill-color', applied.expression)
      }
      if (map.getLayer(id))
        map.setLayoutProperty(id, 'visibility', entry.enabled && applied?.collection ? 'visible' : 'none')
    }
    for (const entry of buildingLayers.filter((item) => item.id !== 'city-osm-3d')) {
      if (!map.getLayer(entry.id)) continue
      const active = entries
        .filter((item) => item.enabled && item.applied?.target === entry.id)
        .sort((a, b) => b.applied.sequence - a.applied.sequence)[0]
      const property = entry.layer.type === 'fill' ? 'fill-color' : 'fill-extrusion-color'
      map.setPaintProperty(entry.id, property, active?.applied.expression ?? entry.layer.paint[property])
    }
  }

  /**
   * Input: một entry sau chọn file/cột/range. Output: snapshot dữ liệu + legend và cập nhật map.
   * Ví dụ CSV ID 123/value 28 -> expression match nd='123'; GeoJSON/BES ngoài -> source fill riêng.
   * Apply lỗi giữ snapshot/map cũ; không âm thầm xóa kết quả người dùng đang xem.
   */
  async function apply(entry) {
    if (entry.loading || !ready.value || disposed) return
    entry.error = ''
    entry.loading = true
    await new Promise((resolve) => setTimeout(resolve, 0))
    if (disposed) return
    try {
      let collection = null,
        values,
        target = entry.target,
        title = entry.valueKey
      if (entry.id === 'bem') {
        if (!entry.data) throw new Error('Load a BES/BEM result file first.')
        values = bemValues(entry.data, Number(entry.variable), Number(entry.timestep))
        title = entry.data.variables[entry.variable] + ' · ' + entry.data.steps[entry.timestep].name
        if (entry.external) {
          if (!entry.geo) throw new Error('Load the external GeoJSON first.')
          collection = valuePolygons(
            entry.geo,
            (feature, index) =>
              values.get(
                entry.geoKey === '@order' ? entry.data.buildingIds[index] : joinKey(feature.properties?.[entry.geoKey]),
              ) ?? null,
          )
          target = 'geojson'
        }
      } else if (entry.target === 'geojson') {
        if (!entry.geo) throw new Error('Load a GeoJSON file first.')
        collection = csvOverlay(entry.geo, entry.csv, entry.csvKey, entry.geoKey, entry.valueKey)
      } else {
        if (!entry.csv) throw new Error('Load a CSV file first.')
        values = csvValues(entry.csv, entry.csvKey, entry.valueKey)
      }
      const style = scalarStyle(
        collection ? collection.features.map((feature) => feature.properties.__city_value) : values.values(),
        entry,
      )
      const expression = collection
        ? ['interpolate', ['linear'], ['get', '__city_value'], ...style.stops]
        : matchColors(values, style)
      entry.applied = markRaw({
        collection,
        target,
        expression,
        style,
        title,
        records: collection ? collection.features.length : values.size,
        sequence: ++sequence,
      })
      if (target !== 'geojson') layerVisibility[target] = true
      sync()
    } catch (error) {
      entry.error = error.message
    } finally {
      entry.loading = false
    }
  }

  function clear(entry) {
    requests.get(entry.id)?.abort()
    entry.applied = null
    entry.error = ''
    sync()
  }

  /** style.load -> dựng lại nguồn từ snapshot đã Apply, không đọc lại file. */
  function restore() {
    sourceData.clear()
    try {
      sync()
    } catch {
      for (const entry of entries)
        if (entry.enabled && entry.applied) entry.error = 'Could not restore visualization layers for this basemap.'
    }
  }

  /** Nguồn lỗi local được cô lập trong HUD tương ứng; không biến thành lỗi toàn basemap. */
  function sourceError(id) {
    const entry = entries.find((item) => overlayId(item) === id)
    if (!entry) return false
    entry.error = 'Could not display this GeoJSON source.'
    return true
  }

  watch(() => entries.map((entry) => entry.enabled), sync)
  watch(
    () => [bem.variable, bem.timestep],
    () => {
      if (bem.enabled && bem.applied && !bem.loading) apply(bem)
    },
  )

  onBeforeUnmount(() => {
    disposed = true
    for (const controller of requests.values()) controller.abort()
    requests.clear()
  })

  return {
    entries,
    load,
    apply,
    clear,
    restore,
    sourceError,
    // Export chỉ cần ID lớp GeoJSON đang bật; geometry được query từ viewport.
    exportLayerIds: () => entries.filter((entry) => entry.enabled && entry.applied?.collection).map(overlayId),
  }
}
