<script setup>
import CityHud from '../components/CityHud.vue'
import GeoJsonImportSettingsHud from './GeoJsonImportSettingsHud.vue'
import StlImportSettingsHud from './StlImportSettingsHud.vue'
import RestApiImportSettingsHud from './RestApiImportSettingsHud.vue'
const props = defineProps({ importer: { type: Object, required: true }, ready: Boolean })
const { geojson, stl, rest } = props.importer
const tools = [
  { label: 'Import STL', controller: stl },
  { label: 'Import GeoJSON', controller: geojson },
  { label: 'Import REST API', controller: rest },
]
</script>

<template>
  <!-- HUD chính chứa ba công tắc Import như bản cũ; state ở controller, HUD cấu hình nằm trong placeholder phái sinh. -->
  <CityHud title="Import" collapsed>
    <VaList class="space-y-1">
      <VaListItem v-for="tool in tools" :key="tool.label" class="rounded-md p-2" tabindex="-1">
        <VaListItemSection
          ><VaListItemLabel :lines="2" class="text-xs font-semibold">{{
            tool.label
          }}</VaListItemLabel></VaListItemSection
        >
        <VaListItemSection icon
          ><VaSwitch v-model="tool.controller.state.enabled" :aria-label="tool.label" size="small" :disabled="!ready"
        /></VaListItemSection>
      </VaListItem>
    </VaList>
  </CityHud>
  <Teleport to="#city-derived-huds" defer>
    <StlImportSettingsHud v-if="stl.state.enabled" :controller="stl" :ready="ready" />
    <GeoJsonImportSettingsHud v-if="geojson.state.enabled" :controller="geojson" :ready="ready" />
    <RestApiImportSettingsHud v-if="rest.state.enabled" :controller="rest" :ready="ready" />
  </Teleport>
</template>
