<script setup>
import { computed } from 'vue'
import CityHud from '../components/CityHud.vue'
import ColorScaleSettings from './ColorScaleSettings.vue'
import { propertyNames } from './csvBesData.js'
const props = defineProps({
  entry: { type: Object, required: true },
  visualization: { type: Object, required: true },
  ready: Boolean,
})
const state = props.entry
const variables = computed(() => state.data?.variables.map((title, value) => ({ title, value })) ?? [])
const timesteps = computed(() => state.data?.steps.map((step, value) => ({ title: step.name, value })) ?? [])
const keys = computed(() => [
  { title: 'Under same order', value: '@order' },
  ...propertyNames(state.geo).map((key) => ({ title: key, value: key })),
])
</script>

<template>
  <!-- Bố cục: Đọc file kết quả BES, chọn biến/timestep, nối với Concordia hoặc GeoJSON ngoài; không chạy solver. -->
  <CityHud title="BES / BEM settings">
    <VaForm novalidate class="space-y-3" @submit.prevent="visualization.apply(state)">
      <VaFileUpload
        v-model="state.dataFile"
        data-testid="bem-file"
        type="single"
        upload-button-text="BES result file"
        file-types=".txt,.out,.dat,.csv"
        :disabled="state.loading"
        @update:modelValue="visualization.load(state, 'data', $event)"
      />
      <VaProgressBar v-if="state.loading" :model-value="state.progress" aria-label="Reading BES results" />
      <VaSelect
        id="city-bem-variable"
        v-model="state.variable"
        :options="variables"
        text-by="title"
        value-by="value"
        label="Variable"
        aria-label="BES variable"
        :disabled="state.loading"
      />
      <VaSelect
        id="city-bem-timestep"
        v-model="state.timestep"
        :options="timesteps"
        text-by="title"
        value-by="value"
        label="Timestep"
        aria-label="BES timestep"
        searchable
        :disabled="state.loading"
      />
      <div class="flex gap-2">
        <VaButton
          size="small"
          icon="ion-md-arrow-back"
          aria-label="Previous timestep"
          :disabled="state.loading || !state.data || state.timestep <= 0"
          @click="state.timestep--"
        />
        <VaButton
          size="small"
          icon="ion-md-arrow-forward"
          aria-label="Next timestep"
          :disabled="state.loading || !state.data || state.timestep >= state.data.steps.length - 1"
          @click="state.timestep++"
        />
      </div>
      <VaSwitch
        v-model="state.external"
        label="External GeoJSON"
        aria-label="External GeoJSON"
        size="small"
        :disabled="state.loading"
      />
      <template v-if="state.external">
        <VaFileUpload
          v-model="state.geoFile"
          data-testid="bem-geojson"
          type="single"
          upload-button-text="BES GeoJSON file"
          file-types=".geojson,.json"
          :disabled="state.loading"
          @update:modelValue="visualization.load(state, 'geo', $event)"
        />
        <VaSelect
          id="city-bem-geo-key"
          v-model="state.geoKey"
          :options="keys"
          text-by="title"
          value-by="value"
          label="Building ID property"
          aria-label="BES building ID property"
          :disabled="state.loading"
        />
      </template>
      <p v-else class="text-xs text-secondary">Building IDs match Concordia 2D by nd.</p>
      <ColorScaleSettings :entry="state" />
      <div class="flex flex-wrap gap-2">
        <VaButton size="small" type="submit" :disabled="!ready || state.loading">Apply</VaButton>
        <VaButton
          size="small"
          preset="secondary"
          :disabled="state.loading || !state.applied"
          @click="visualization.clear(state)"
          >Clear colors</VaButton
        >
      </div>
      <VaAlert v-if="state.error" color="danger" dense outline class="mb-0 text-xs break-words">{{
        state.error
      }}</VaAlert>
    </VaForm>
  </CityHud>
</template>
