<script setup>
import { computed } from 'vue'
import CityHud from '../components/CityHud.vue'
import ColorScaleSettings from './ColorScaleSettings.vue'
import { propertyNames } from './csvBesData.js'
const props = defineProps({
  entry: { type: Object, required: true },
  visualization: { type: Object, required: true },
  ready: Boolean,
})
const state = props.entry
const properties = computed(() => propertyNames(state.geo))
const values = computed(() => [...new Set([...(state.csv?.headers ?? []), ...properties.value])])
</script>

<template>
  <!-- Bố cục: HUD phái sinh cho CSV/GeoJSON hoặc CSV lên building 2D/3D; state sống trong controller nên thu gọn/ẩn không mất dữ liệu. -->
  <CityHud :title="state.label + ' settings'">
    <VaForm novalidate class="space-y-3" @submit.prevent="visualization.apply(state)">
      <VaFileUpload
        v-if="state.target === 'geojson'"
        v-model="state.geoFile"
        :data-testid="state.id + '-geojson'"
        type="single"
        upload-button-text="GeoJSON file"
        file-types=".json,.geojson"
        :disabled="state.loading"
        @update:modelValue="visualization.load(state, 'geo', $event)"
      />
      <VaFileUpload
        v-model="state.csvFile"
        :data-testid="state.id + '-csv'"
        type="single"
        :upload-button-text="state.target === 'geojson' ? 'CSV file (optional)' : 'CSV file'"
        file-types=".csv,.txt"
        :disabled="state.loading"
        @update:modelValue="visualization.load(state, 'csv', $event)"
      />
      <VaProgressBar v-if="state.loading" indeterminate aria-label="Reading visualization data" />
      <!-- Chỉ cần khóa nối khi có CSV; GeoJSON không có CSV sử dụng trực tiếp thuộc tính số của polygon. -->
      <VaSelect
        v-if="state.csv"
        v-model="state.csvKey"
        :options="state.csv.headers"
        label="CSV ID column"
        aria-label="CSV ID column"
        :disabled="state.loading"
      />
      <VaSelect
        v-if="state.target === 'geojson' && state.csv"
        v-model="state.geoKey"
        :options="properties"
        label="GeoJSON ID property"
        aria-label="GeoJSON ID property"
        :disabled="state.loading"
      />
      <VaSelect
        :id="state.id + '-value'"
        v-model="state.valueKey"
        :options="values"
        label="Value column"
        aria-label="Value column"
        :disabled="state.loading"
      />
      <p v-if="state.target !== 'geojson'" class="text-xs text-secondary">
        CSV IDs match the Concordia building property nd.
      </p>
      <ColorScaleSettings :entry="state" />
      <div class="flex flex-wrap gap-2">
        <VaButton size="small" type="submit" :disabled="!ready || state.loading" :loading="state.loading"
          >Apply</VaButton
        >
        <VaButton
          size="small"
          preset="secondary"
          :disabled="state.loading || !state.applied"
          @click="visualization.clear(state)"
          >Clear colors</VaButton
        >
      </div>
      <VaAlert v-if="state.error" color="danger" dense outline class="mb-0 text-xs break-words">{{
        state.error
      }}</VaAlert>
    </VaForm>
  </CityHud>
</template>
