<script setup>
import CityHud from '../components/CityHud.vue'
const props = defineProps({ exporter: { type: Object, required: true }, ready: Boolean })
const state = props.exporter.state
</script>

<template>
  <!-- Bố cục: Chọn vùng → chọn nguồn → tùy chọn origin/đầu ra → preview và export ZIP; không tải file trước khi toàn bộ tác vụ thành công. -->
  <CityHud title="STL export settings">
    <VaForm novalidate class="space-y-3" @submit.prevent="exporter.exportZip()">
      <VaSelect
        id="city-export-selection"
        v-model="state.mode"
        label="Selection"
        aria-label="Export selection"
        text-by="title"
        value-by="value"
        :options="[
          { title: 'Draw polygon', value: 'polygon' },
          { title: 'Two corners', value: 'bbox' },
        ]"
        :disabled="state.busy"
      />
      <VaButton
        v-if="state.mode === 'polygon'"
        size="small"
        :disabled="!ready || state.busy"
        @click="exporter.drawRegion()"
        >Draw region</VaButton
      >
      <template v-else>
        <div class="grid grid-cols-2 gap-2">
          <VaInput
            v-model="state.p1Lng"
            type="number"
            label="Corner 1 longitude"
            input-aria-label="Corner 1 longitude"
            :disabled="state.busy"
          />
          <VaInput
            v-model="state.p1Lat"
            type="number"
            label="Corner 1 latitude"
            input-aria-label="Corner 1 latitude"
            :disabled="state.busy"
          />
          <VaInput
            v-model="state.p2Lng"
            type="number"
            label="Corner 2 longitude"
            input-aria-label="Corner 2 longitude"
            :disabled="state.busy"
          />
          <VaInput
            v-model="state.p2Lat"
            type="number"
            label="Corner 2 latitude"
            input-aria-label="Corner 2 latitude"
            :disabled="state.busy"
          />
        </div>
        <VaButton size="small" preset="secondary" :disabled="!ready || state.busy" @click="exporter.showBounds()"
          >Show region</VaButton
        >
      </template>
      <VaButton size="small" preset="secondary" :disabled="state.busy" @click="exporter.clearRegion()"
        >Clear drawing</VaButton
      >
      <p v-if="state.drawing" class="text-xs">
        Click corners on the map. Click the first point to finish; Escape cancels drawing.
      </p>
      <VaDivider />
      <!-- Include chỉ chọn nguồn để query; không tự bật các layer bản đồ. Hai lớp Concordia được gom để không xuất trùng 2D/3D. -->
      <VaCheckbox v-model="state.concordia" label="Concordia buildings" :disabled="state.busy" />
      <VaCheckbox v-model="state.osm" label="Default OSM buildings" :disabled="state.busy" />
      <VaCheckbox v-model="state.geojson" label="Visualized GeoJSON" :disabled="state.busy" />
      <VaCheckbox v-model="state.importedGeojson" label="Imported GeoJSON buildings" :disabled="state.busy" />
      <VaCheckbox v-model="state.includeImportedModels" label="Imported STL models" :disabled="state.busy" />
      <VaCheckbox v-model="state.includeAdditionalModels" label="Additional STL models" :disabled="state.busy" />
