        <div v-for="(model, index) in state.additionalModels" :key="index" class="space-y-2">
          <p class="text-xs break-words">{{ model.name }}</p>
          <VaAlert v-if="model.error" color="warning" dense outline class="mb-0 text-xs break-words">{{
            model.error
          }}</VaAlert>
