            <div class="grid grid-cols-2 gap-2">
              <VaInput
                v-model="model.lng"
                type="number"
                :label="'Model ' + (index + 1) + ' longitude'"
                :input-aria-label="'Model ' + (index + 1) + ' longitude'"
                :disabled="state.busy"
              />
              <VaInput
                v-model="model.lat"
                type="number"
                :label="'Model ' + (index + 1) + ' latitude'"
                :input-aria-label="'Model ' + (index + 1) + ' latitude'"
                :disabled="state.busy"
              />
            </div>
          </template>
        </div>
        <p class="text-xs text-secondary">
          Coordinates locate the STL origin. Additional STL models are merged whole. This does not add a preview layer
