          type="number"
          label="Origin longitude"
          input-aria-label="Origin longitude"
          :disabled="state.busy"
        />
        <VaInput
          v-model="state.originLat"
          type="number"
          label="Origin latitude"
          input-aria-label="Origin latitude"
          :disabled="state.busy"
        />
      </div>
      <VaSelect
        v-model="state.projection"
        label="Projection"
        aria-label="STL projection"
        text-by="title"
        value-by="value"
        :options="[
          { title: 'Local metres', value: 'local' },
          { title: 'Legacy Web Mercator', value: 'web-mercator' },
        ]"
        :disabled="state.busy"
      />
      <VaCheckbox v-model="state.domain" label="domain.txt" :disabled="state.busy" />
      <VaCheckbox v-model="state.info" label="Building info + GeoJSON" :disabled="state.busy" />
      <template v-if="state.info">
        <VaSelect
          v-model="state.yearKey"
          :options="state.properties"
          label="Year property"
          aria-label="Building year property"
          :disabled="state.busy"
          clearable
        />
        <VaSelect
          v-model="state.typeKey"
          :options="state.properties"
          label="Type property"
          aria-label="Building type property"
          :disabled="state.busy"
          clearable
        />
      </template>
      <VaCheckbox v-model="state.position" label="positionSetting.txt" :disabled="state.busy" />
      <p class="text-xs text-secondary">
