      </p>
      <div class="flex flex-wrap gap-2">
        <VaButton size="small" preset="secondary" :disabled="!ready || state.busy" @click="exporter.preview()"
          >Preview selection</VaButton
        >
        <VaButton size="small" type="submit" :disabled="!ready || state.busy || state.loadingModels"
          >Export ZIP</VaButton
        >
        <VaButton v-if="state.busy" size="small" color="warning" @click="exporter.cancel()">Cancel export</VaButton>
      </div>
      <p v-if="state.preview" class="text-xs" data-testid="export-preview">
