      <VaAlert v-if="state.warning" color="warning" dense outline class="mb-0 text-xs break-words">{{
        state.warning
      }}</VaAlert>
      <VaAlert v-if="state.error" color="danger" dense outline class="mb-0 text-xs break-words">{{
        state.error
      }}</VaAlert>
      <VaAlert v-if="state.message" color="info" dense outline class="mb-0 text-xs break-words">{{
        state.message
      }}</VaAlert>
    </VaForm>
  </CityHud>
</template>
