import { useCsvBesVisualization } from './useCsvBesVisualization.js'
import { useCfdVisualization } from './useCfdVisualization.js'

/**
 * Input: getMap/ready/layerVisibility từ owner. Output: hai controller csvBes và cfd, dùng cùng một Mapbox.
 * HUD gọi trực tiếp controller tương ứng; coordinator chỉ nối restore theo style và chuyển nguồn GeoJSON cho Export.
 * File không giữ file input, state màu hoặc GPU: từng tính năng tự sở hữu state, watcher, hủy đọc và cleanup.
 */
export function useVisualization(options) {
  const csvBes = useCsvBesVisualization(options)
  const cfd = useCfdVisualization(options)
  return {
    csvBes,
    cfd,
    restore() {
      csvBes.restore()
      cfd.restore()
    },
    sourceError: csvBes.sourceError,
    exportLayerIds: csvBes.exportLayerIds,
  }
}
