/**
 * Các field popup building đã có ở dự án cũ, bổ sung nd dưới nhãn Dataset ID.
 * Các ID giữ riêng: nd không được suy diễn thành OSM ID.
 */
const buildingFields = [
  ['Dataset ID', 'nd'],
  ['Construction year', 'ANNEE_CONS'],
  ['Street', 'NOM_RUE'],
  ['Height (m)', 'height'],
  ['Category code', 'CATEGORIE_'],
  ['Address from', 'CIVIQUE_DE'],
  ['Address to', 'CIVIQUE_FI'],
  ['Use code', 'CODE_UTILI'],
  ['Floors above ground', 'ETAGE_HORS'],
  ['Building use', 'LIBELLE_UT'],
  ['OSM ID', 'nodeid'],
]

/**
 * Chuẩn hóa thuộc tính từ vector tile cho Vue hiển thị bằng text binding.
 *
 * @param {object|null} properties Ví dụ { nd: 123, height: "36", NOM_RUE: "A < B" }.
 * @returns {Array<{label: string, value: string}>} Ví dụ:
 * [{ label: "Dataset ID", value: "123" }, ... { label: "Street", value: "A < B" }].
 *
 * Field thiếu, chuỗi trắng, số không hữu hạn hoặc object -> "—"; số 0 vẫn là "0".
 * Không ghép HTML và không dùng v-html. Chuỗi "<img ...>" vẫn là text để Vue escape,
 * không trở thành phần tử thực thi. Không tự suy đoán/giải mã các mã phân loại.
 */
export function getBuildingDetails(properties) {
  return buildingFields.map(([label, key]) => {
    const value = properties?.[key]
    const valid =
      (typeof value === 'string' && value.trim() !== '') || (typeof value === 'number' && Number.isFinite(value))
    return { label, value: valid ? String(value) : '—' }
  })
}
