<script setup>
import { useCityMap } from './useCityMap.js'
import LayerHud from './layer/LayerHud.vue'
import ImportHud from './import/ImportHud.vue'
import VisualizeHud from './visualize/VisualizeHud.vue'
import ExportHud from './export/ExportHud.vue'
import '@mapbox/mapbox-gl-draw/dist/mapbox-gl-draw.css'
import 'mapbox-gl/dist/mapbox-gl.css'
import '@mapbox/mapbox-gl-geocoder/dist/mapbox-gl-geocoder.css'
import 'ionicons/dist/css/ionicons.min.css'

// Một owner cho Mapbox; từng HUD chỉ nhận module logic của mình, popup và toolbar có controller riêng.
const city = useCityMap()
const { mapElement, initialized, ready, error, isDark } = city
const { controlsElement, searchError, controlsVisible, layersOpen, mapStyle, mapStyles } = city.controls
const { popupElement, selectedFeature, closeFeature } = city.details
</script>

<template>
  <!-- Bố cục: Mapbox là nền toàn view; controls nằm bên phải, các CityHud nằm bên trái, popup và thông báo tải/lỗi phủ lên bản đồ. -->
  <section
    class="city-map-shell relative h-full min-h-0"
    :class="{ 'city-map-shell--light': !isDark }"
    @keydown.esc="closeFeature"
  >
    <!-- Mapbox tạo canvas trong div này; không gắn HUD vào bên trong container mà thư viện đang quản lý. -->
    <div
      ref="mapElement"
      class="city-map"
      :class="{ 'city-map--hide-controls': !controlsVisible }"
      aria-label="City map"
      :aria-busy="!ready && !error"
    />
    <!-- Toolbar Vue được chuyển vào Mapbox qua controlsElement, đặt cùng cột với search và zoom. -->
    <aside
      v-show="initialized"
      ref="controlsElement"
      class="city-actions mapboxgl-ctrl flex flex-col gap-2"
      aria-label="Map settings"
    >
      <VaDropdown
        v-model="layersOpen"
        aria-label="Map layers"
        placement="left-start"
        :offset="[8, 0]"
        :close-on-content-click="false"
        stick-to-edges
      >
        <template #anchor>
          <VaButton
            class="city-glass"
            color="backgroundElement"
            text-color="textPrimary"
            size="small"
            icon="ion-md-albums"
            aria-label="Map layers"
            title="Map layers"
            aria-controls="city-layer-menu"
            :aria-expanded="layersOpen"
          />
        </template>
        <VaDropdownContent id="city-layer-menu" class="city-glass city-layer-menu">
          <VaSelect
            id="city-map-style"
            v-model="mapStyle"
            label="Basemap"
            aria-label="Map style"
            text-by="title"
            value-by="value"
            :options="mapStyles"
          />
        </VaDropdownContent>
      </VaDropdown>
      <VaButton
        class="city-glass"
        color="backgroundElement"
        text-color="textPrimary"
        size="small"
        :icon="controlsVisible ? 'ion-md-eye' : 'ion-md-eye-off'"
        :aria-pressed="!controlsVisible"
        aria-controls="city-primary-huds city-derived-huds"
        :aria-label="controlsVisible ? 'Hide map controls' : 'Show map controls'"
        :title="controlsVisible ? 'Hide map controls' : 'Show map controls'"
        @click="controlsVisible = !controlsVisible"
      />
    </aside>
    <!-- Hai placeholder chỉ giữ vị trí, trong suốt và không chặn thao tác map ở vùng trống.
         Bốn module chính (Layer, Import, Visualize, Export) đặt ở cột đầu và Teleport HUD con vào cột phái sinh.
         v-show ẩn cả hai cột nhưng giữ các module và trạng thái thu gọn. -->
    <div v-show="controlsVisible" class="city-hud-stack">
      <div id="city-primary-huds" class="city-hud-slot" role="region" aria-label="Main HUDs">
        <LayerHud :layers="city.layers" />
        <ImportHud :importer="city.importer" :ready="ready" />
        <VisualizeHud :visualization="city.visualization" :ready="ready" />
        <ExportHud :exporter="city.exporter" :ready="ready" />
      </div>
      <div id="city-derived-huds" class="city-hud-slot" role="region" aria-label="Derived HUDs" />
    </div>
    <!-- Vue tạo nội dung chi tiết; Mapbox chỉ định vị DOM này theo tọa độ đối tượng được chọn. -->
    <div
      v-show="selectedFeature"
      ref="popupElement"
      class="city-feature-popup"
      role="dialog"
      :aria-label="selectedFeature?.title || 'Feature details'"
    >
      <VaCard class="city-glass" color="backgroundElement" text-color="textPrimary">
        <VaCardTitle class="justify-between gap-2 !p-3 !pb-2">
          <h2 class="text-sm font-semibold normal-case tracking-normal">{{ selectedFeature?.title }}</h2>
          <VaButton
            preset="plain"
            color="textPrimary"
            icon="ion-md-close"
            size="small"
            aria-label="Close feature details"
            @click="closeFeature"
          />
        </VaCardTitle>
        <VaCardContent class="max-h-[45dvh] overflow-y-auto !p-3 !pt-0">
          <dl class="grid grid-cols-[auto_minmax(0,1fr)] gap-x-3 gap-y-2 text-xs">
            <template v-for="row in selectedFeature?.rows" :key="row.label"
              ><dt class="text-secondary">{{ row.label }}</dt>
              <dd class="break-words">{{ row.value }}</dd></template
            >
          </dl>
        </VaCardContent>
      </VaCard>
    </div>
    <div v-if="(!ready && !error) || error || searchError" class="city-status">
      <VaProgressBar v-if="!ready && !error" indeterminate aria-label="Loading map" />
      <VaAlert v-if="error || searchError" color="danger" role="alert" data-testid="city-error" class="break-words">
        {{ error || searchError }}
      </VaAlert>
    </div>
  </section>
</template>

