import { markRaw, onBeforeUnmount, reactive, watch } from 'vue'
import { numeric } from './csvBesData.js'
import { readPosition, readWind, readWindJson, sliceInfo, windDemo } from './cfdData.js'
import { createWindLayer, WIND_LAYER_ID } from './cfdLayer.js'

/**
 * Input: getMap() và ready ref. Output: state riêng cho CfdSettingsHud cùng load/loadPosition/position/clear/restore.
 * load(File) -> field local đã validate; load(null,true) -> fetch demo theo yêu cầu, không tải khi chỉ mở trang.
 * Ví dụ state.side='XZ', level=5 -> configure cùng custom layer ở y=5*hy; pause/speed/size chỉ yêu cầu repaint.
 * Tắt lớp/đổi style/rời trang dọn GPU; field còn trong RAM khi tắt và dùng lại khi bật. Fetch/parser được hủy khi rời trang.
 */
export function useCfdVisualization({ getMap, ready }) {
  const wind = reactive({
    enabled: false,
    file: [],
    positionFile: [],
    loading: false,
    progress: 0,
    error: '',
    field: null,
    name: '',
    lng: windDemo.origin[0],
    lat: windDemo.origin[1],
    origin: markRaw([...windDemo.origin]),
    side: 'XZ',
    slice: true,
    level: 5,
    pointSize: 7,
    speed: 0.1,
    paused: false,
    contours: false,
    contourLevels: 20,
  })

  // Chỉ một field CFD được tải tại một thời điểm; giữ controller để hủy và nhận diện lượt hiện hành.
  let loadController = null,
    disposed = false,
    windLayer = null

  function validOrigin() {
    const lng = numeric(wind.lng),
      lat = numeric(wind.lat)
    if (lng === null || lat === null || Math.abs(lng) > 180 || Math.abs(lat) > 85.051129)
      throw new Error('CFD origin must be a valid WGS84 longitude and latitude.')
    return [lng, lat]
  }

  /** Chỉ cập nhật tọa độ render sau validate; gõ dở input không đẩy NaN vào WebGL. */
  function positionWind(fly = true) {
    try {
      wind.origin = markRaw(validOrigin())
      wind.error = ''
      const map = getMap()
      if (fly) map?.flyTo({ center: wind.origin, zoom: 16, pitch: 55 })
      map?.triggerRepaint()
    } catch (error) {
      wind.error = error.message
    }
  }

  function syncWind() {
    const map = getMap()
    if (!map || !ready.value || disposed) return
    if (map.getLayer(WIND_LAYER_ID) && (!wind.enabled || windLayer?.field !== wind.field)) {
      map.removeLayer(WIND_LAYER_ID)
      windLayer = null
    }
    if (wind.enabled && wind.field && !map.getLayer(WIND_LAYER_ID)) {
      try {
        windLayer = createWindLayer(wind.field, wind)
        windLayer.field = wind.field
        map.addLayer(windLayer)
      } catch {
        wind.error = 'Could not render the CFD field. Check browser WebGL support.'
      }
    }
    map.triggerRepaint()
  }

  /** Input: local Tecplot file hoặc demo=true. Output: field đã validate, đặt vị trí và render nếu CFD đang bật. */
  async function loadWind(input, demo = false) {
    loadController?.abort()
    const file = Array.isArray(input) ? input[0] : input
    if (!demo && !file) {
      clearWind()
      return
    }
    const controller = new AbortController()
    loadController = controller
    wind.loading = true
    wind.progress = 0
    wind.error = ''
    try {
      const origin = validOrigin()
      let field
      if (demo) {
        const response = await fetch(windDemo.url, { signal: controller.signal })
        if (!response.ok) throw new Error('Demo request failed (HTTP ' + response.status + ').')
        field = readWindJson(await response.json())
      } else
        field = await readWind(file, {
          signal: controller.signal,
          onProgress: (value) => {
            if (!controller.signal.aborted) wind.progress = value
          },
        })
      controller.signal.throwIfAborted()
      if (disposed) return
      wind.field = markRaw(field)
      wind.name = demo ? 'Concordia demo' : file.name
      wind.origin = markRaw(origin)
      wind.level = Math.min(5, sliceInfo(field, wind.side).max)
      syncWind()
      positionWind()
    } catch (error) {
      if (!controller.signal.aborted && !disposed) wind.error = error.message
    } finally {
      if (loadController === controller) {
        wind.loading = false
        loadController = null
      }
    }
  }

  async function loadWindPosition(input) {
    const file = Array.isArray(input) ? input[0] : input
    if (!file) return
    try {
      const point = readPosition(await file.text())
      if (!disposed) {
        ;[wind.lng, wind.lat] = point
        positionWind(false)
      }
    } catch (error) {
      if (!disposed) wind.error = error.message
    }
  }

  function clearWind() {
    loadController?.abort()
    wind.field = null
    // VaFileUpload nhận [] khi rỗng; null bị coi là một file và lỗi khi đọc name.
    wind.file = []
    wind.name = ''
    wind.error = ''
    syncWind()
  }

  function restore() {
    windLayer = null
    syncWind()
  }

  watch(
    () => wind.enabled,
    (enabled) => {
      if (!enabled) loadController?.abort()
      syncWind()
    },
  )
  watch(
    () => [wind.side, wind.level, wind.slice, wind.contours, wind.contourLevels],
    ([side], [previousSide]) => {
      if (wind.field && side !== previousSide) wind.level = Math.floor(sliceInfo(wind.field, side).max / 2)
      windLayer?.configure()
    },
  )
  watch(
    () => [wind.pointSize, wind.speed, wind.paused],
    () => getMap()?.triggerRepaint(),
  )

  onBeforeUnmount(() => {
    disposed = true
    loadController?.abort()
    loadController = null
    const map = getMap()
    if (map?.getLayer(WIND_LAYER_ID)) map.removeLayer(WIND_LAYER_ID)
  })

  return {
    state: wind,
    load: loadWind,
    loadPosition: loadWindPosition,
    position: positionWind,
    clear: clearWind,
    restore,
  }
}
