import union from '@turf/union'
import intersect from '@turf/intersect'
import booleanIntersects from '@turf/boolean-intersects'
import { coordEach } from '@turf/meta'
import { joinKey, numeric, readPolygons } from '../visualize/csvBesData.js'
import { buildingLayers } from '../layer/buildingLayers.js'
import { GEOJSON_IMPORT_ID } from '../import/importData.js'
import {
  geojsonToStlAsync,
  makeProjector,
  makeUnprojector,
  buildBuildingInfoText,
  buildDomainText,
} from '../../preprocessing/stl-converter/geojsonToStl.js'

const collection = (features) => ({ type: 'FeatureCollection', features })

/** Input: longitude/latitude người dùng nhập. Output: tọa độ hữu hạn WGS84; input trống/NaN/ngoài Mercator -> lỗi. */
export function validLngLat(lng, lat) {
  const x = numeric(lng),
    y = numeric(lat)
  if (x === null || y === null || Math.abs(x) > 180 || Math.abs(y) > 85.051129)
    throw new Error('Coordinates must be valid WGS84 longitude/latitude within the Mercator map.')
  return [x, y]
}

/** Input: Polygon/MultiPolygon Feature. Output: [west,south,east,north] từ tất cả các ring, không phụ thuộc viewport. */
export function geometryBounds(feature) {
  const bounds = [Infinity, Infinity, -Infinity, -Infinity]
  coordEach(feature, (point) => {
    bounds[0] = Math.min(bounds[0], point[0])
    bounds[1] = Math.min(bounds[1], point[1])
    bounds[2] = Math.max(bounds[2], point[0])
    bounds[3] = Math.max(bounds[3], point[1])
  })
  if (!bounds.every(Number.isFinite)) throw new Error('The selected region has no valid coordinates.')
  return bounds
}

/** Input: 2 góc WGS84 bất kỳ thứ tự. Output: polygon bbox kín; bbox rỗng hoặc qua kinh tuyến 180 bị từ chối. */
export function bboxRegion(p1, p2) {
  const a = validLngLat(...p1),
    b = validLngLat(...p2)
  const west = Math.min(a[0], b[0]),
    east = Math.max(a[0], b[0]),
    south = Math.min(a[1], b[1]),
    north = Math.max(a[1], b[1])
  if (west === east || south === north || east - west >= 180)
    throw new Error('Choose a non-empty region that does not cross the antimeridian.')
  return {
    type: 'Feature',
    properties: {},
    geometry: {
      type: 'Polygon',
      coordinates: [
        [
          [west, south],
          [east, south],
          [east, north],
          [west, north],
          [west, south],
        ],
      ],
    },
  }
}

/** Input: polygon vẽ hoặc bbox. Output: vùng đã validate, square bbox và tâm; giữ quy tắc square(bbox) bằng độ của exporter cũ. */
export function resolveRegion(feature) {
  const polygon = readPolygons(JSON.stringify(collection([feature]))).features[0]
  const bounds = geometryBounds(polygon)
  if (bounds[0] === bounds[2] || bounds[1] === bounds[3] || bounds[2] - bounds[0] >= 180)
    throw new Error('The export region is empty or crosses the antimeridian.')
  const center = [(bounds[0] + bounds[2]) / 2, (bounds[1] + bounds[3]) / 2]
  const span = Math.max(bounds[2] - bounds[0], bounds[3] - bounds[1]) / 2
  const square = bboxRegion([center[0] - span, center[1] - span], [center[0] + span, center[1] + span])
  return { polygon, bounds, square, squareBounds: geometryBounds(square), center }
}

/**
 * Input: queryRenderedFeatures và polygon chọn. Output: FeatureCollection đã gom tile fragment, lọc giao polygon, cắt theo square bbox.
 * Chỉ gộp fragment cùng nguồn, source-layer, ID và cao độ; giữ riêng từng phần cao/thấp của một nhà.
 * Dùng nd/osm_id làm ID output để Building_info khớp BES; không dùng nhầm tile feature ID làm building ID.
 * Height thiếu/không dương bị bỏ có thống kê; lỗi union/cắt không được âm thầm lấy mất một fragment.
 */
export function selectBuildings(rendered, region) {
  const byId = new Map()
  let skipped = 0
  for (const raw of rendered) {
    if (!['Polygon', 'MultiPolygon'].includes(raw.geometry?.type)) {
      skipped++
      continue
    }
    const props = { ...raw.properties }
    const native = buildingLayers.some((entry) => entry.id === raw.layer?.id)
    // Đồng nhất với paint của City: native dùng height; GeoJSON Import luôn có đáy ở 0.
    const height = native ? Number(props.height) : (numeric(props.h) ?? numeric(props.height))
    const baseValue = Number(props.min_height)
    const base = raw.layer?.id === GEOJSON_IMPORT_ID || !Number.isFinite(baseValue) ? 0 : Math.max(0, baseValue)
    if (!Number.isFinite(height) || height <= 0 || base >= height) {
      skipped++
      continue
    }
    props.h = height
    props.min_height = base
    const id = [props.nd, props.osm_id, raw.id, props.id, props.auto_id].find((value) => joinKey(value) !== null)
    const source = raw.source ?? raw.layer?.source ?? 'geojson'
    const identity = id === undefined ? JSON.stringify(raw.geometry) : String(id)
    const sourceLayer = raw.sourceLayer ?? raw.layer?.['source-layer'] ?? ''
    const key = JSON.stringify([source, sourceLayer, identity, height, base])
    const feature = { type: 'Feature', ...(id === undefined ? {} : { id }), properties: props, geometry: raw.geometry }
    if (!byId.has(key)) byId.set(key, feature)
    else {
      const previous = byId.get(key)
      if (JSON.stringify(previous.geometry) === JSON.stringify(feature.geometry)) continue
      const merged = union(collection([previous, feature]))
      if (!merged) throw new Error('Could not merge building fragments for ID ' + identity + '.')
      byId.set(key, { ...feature, geometry: merged.geometry })
    }
  }
  const features = []
  for (const feature of byId.values()) {
    if (!booleanIntersects(feature, region.polygon)) continue
    const bounds = geometryBounds(feature),
      box = region.squareBounds
    if (bounds[0] >= box[0] && bounds[1] >= box[1] && bounds[2] <= box[2] && bounds[3] <= box[3]) features.push(feature)
    else {
      const clipped = intersect(collection([region.square, feature]))
      if (clipped) features.push({ ...feature, geometry: clipped.geometry })
    }
  }
  return { collection: collection(features), skipped }
}

/** Input: parsed STL models với lng/lat/projection và origin xuất. Output: solids [east,up,south] cùng hệ quy chiếu building. */
export function placeModels(models, origin, projection) {
  const project = makeProjector(origin, projection)
  return models.flatMap((model, index) => {
    const unproject = makeUnprojector(validLngLat(model.lng, model.lat), model.projection ?? 'local')
    const stem = model.name.replace(/\.[^.]+$/, '').replace(/\W+/g, '_')
    // Đổi qua WGS84 trước khi đổi origin/projection; chỉ cộng offset sẽ làm sai tỉ lệ STL đã import.
    return model.parsed.solids.map((solid) => {
      const positions = solid.positions.slice()
      for (let i = 0; i < positions.length; i += 3) {
        const [east, north] = project(unproject([positions[i], -positions[i + 2]]))
        positions[i] = east
        positions[i + 2] = -north || 0
      }
      return { ...solid, positions, name: 'import_' + index + '_' + stem + '_' + solid.name, source: model.name }
    })
  })
}

/**
 * Input: collection đã chọn/cắt và options origin/projection, extraModels, domain/info/position, yearKey/typeKey.
 * Output: {result, files:[{name,content}]}; filenames giữ geometry.stl/domain.txt/Building_info.txt/selected_features.geojson/positionSetting.txt.
 * Không tải file tại đây: controller chỉ download ZIP khi toàn bộ chuyển đổi thành công và chưa bị hủy.
 */
export async function createExportFiles(selected, options, control = {}) {
  const origin = validLngLat(...options.origin)
  if (!['local', 'web-mercator'].includes(options.projection)) throw new Error('Unsupported STL projection.')
  // City xuất building; cột dữ liệu a vẫn giữ trong metadata, không dùng để nhận diện terrain của core.
  const buildings = collection(
    selected.features.map((feature) => ({
      ...feature,
      properties: { ...feature.properties, a: undefined },
    })),
  )
  const result = await geojsonToStlAsync(
    buildings,
    {
      origin,
      projection: options.projection,
      heightProperty: 'h',
      baseProperty: 'min_height',
      extraSolids: placeModels(options.extraModels ?? [], origin, options.projection),
    },
    control,
  )
  if (control.shouldCancel?.()) {
    const error = new Error('Export cancelled.')
    error.cancelled = true
    throw error
  }
  if (!result.stats.buildings && !result.stats.imported)
    throw new Error('No usable building or STL geometry was found to export.')
  const files = [{ name: 'geometry.stl', content: new Blob(result.chunks, { type: 'model/stl' }) }]
  if (options.domain) files.push({ name: 'domain.txt', content: buildDomainText(result) })
  if (options.info)
    files.push(
      { name: 'Building_info.txt', content: buildBuildingInfoText(result, selected, options.yearKey, options.typeKey) },
      { name: 'selected_features.geojson', content: JSON.stringify(selected) },
    )
  if (options.position)
    files.push({
      name: 'positionSetting.txt',
      content: JSON.stringify({
        type: 'Feature',
        properties: { projection: result.projection, note: 'STL origin (0,0,0) in WGS84' },
        geometry: { type: 'Point', coordinates: result.origin },
      }),
    })
  return { result, files }
}
