<script setup>
import CityHud from '../components/CityHud.vue'
import ShadingHud from './ShadingHud.vue'

const props = defineProps({ layers: { type: Object, required: true } })
// Chỉ nhận state của useMapLayers; Shading có controller riêng, cùng sử dụng Mapbox do owner quản lý.
const {
  ready,
  buildingLayers,
  layerVisibility,
  layerErrors,
  layerErrorMessages,
  mapOverlays,
  overlayVisibility,
  overlayErrors,
  shadingControls,
  enabledLayerCount,
} = props.layers
const { shading } = shadingControls
</script>

<template>
  <!-- Bố cục: HUD chính chứa công tắc building, overlay và Shading, dùng khung CityHud chung. -->
  <CityHud id="city-layer-hud" title="Layer" collapsed>
    <template #header-extra>
      <VaChip
        size="small"
        color="primary"
        text-color="textPrimary"
        flat
        readonly
        :aria-label="enabledLayerCount + ' layers enabled'"
      >
        <!-- {{ enabledLayerCount }}/{{ buildingLayers.length + mapOverlays.length + 1 }} -->
      </VaChip>
    </template>
    <VaList class="space-y-1">
      <VaListItem
        v-for="entry in buildingLayers"
        :key="entry.id"
        class="city-building-row rounded-md p-2"
        :class="{ 'bg-backgroundPrimary': layerVisibility[entry.id] && !layerErrors[entry.id] }"
        :data-testid="'layer-' + entry.id"
        tabindex="-1"
      >
        <VaListItemSection>
          <VaListItemLabel :lines="2" class="text-xs font-semibold" :title="entry.description">
            {{ entry.label }}
          </VaListItemLabel>
          <VaListItemLabel v-if="layerErrors[entry.id]" caption>Unavailable</VaListItemLabel>
        </VaListItemSection>
        <VaListItemSection icon>
          <VaSwitch v-model="layerVisibility[entry.id]" :aria-label="entry.label" :disabled="!ready" size="small" />
        </VaListItemSection>
      </VaListItem>

      <VaListItem v-for="entry in mapOverlays" :key="entry.id" class="city-building-row rounded-md p-2" tabindex="-1">
        <VaListItemSection>
          <VaListItemLabel :lines="2" class="text-xs font-semibold" :title="entry.description">{{
            entry.label
          }}</VaListItemLabel>
          <VaListItemLabel v-if="overlayErrors[entry.id]" caption>Unavailable</VaListItemLabel>
        </VaListItemSection>
        <VaListItemSection icon>
          <VaSwitch v-model="overlayVisibility[entry.id]" :aria-label="entry.label" :disabled="!ready" size="small" />
        </VaListItemSection>
      </VaListItem>
      <VaListItem class="city-building-row rounded-md p-2" tabindex="-1">
        <VaListItemSection><VaListItemLabel class="text-xs font-semibold">Shading</VaListItemLabel></VaListItemSection>
        <VaListItemSection icon
          ><VaSwitch v-model="shading.enabled" aria-label="Shading" :disabled="!ready" size="small"
        /></VaListItemSection>
      </VaListItem>
    </VaList>
    <VaAlert
      v-for="message in [...layerErrorMessages, ...Object.values(overlayErrors)]"
      :key="message"
      color="danger"
      dense
      outline
      class="mb-0 text-xs"
      >{{ message }}</VaAlert
    >
  </CityHud>
  <!-- Teleport chỉ chuyển DOM; state vẫn thuộc CityView. defer chờ vùng phái sinh render trong cùng lượt cập nhật. -->
  <Teleport to="#city-derived-huds" defer>
    <ShadingHud v-if="shading.enabled" :controls="shadingControls" />
  </Teleport>
</template>
