import { markRaw, onBeforeUnmount, reactive, watch } from 'vue'
import { propertyNames, readPolygons } from '../visualize/csvBesData.js'
import { buildingGeojson, GEOJSON_IMPORT_ID } from './importData.js'

/** Input: getMap/ready. Output: state chọn file/cột height/Append, load/apply/clear và restore cho HUD Import GeoJSON.
 * Load chỉ đọc form; Apply thay/nối snapshot đang vẽ. File lỗi không xóa dữ liệu đã nhập; tắt HUD chỉ ẩn lớp.
 */
export function useGeojsonImport({ getMap, ready }) {
  const empty = () => ({ type: 'FeatureCollection', features: [] })
  const state = reactive({
    enabled: false,
    file: [],
    loading: false,
    error: '',
    pending: null,
    properties: [],
    heightKey: '',
    append: false,
    collection: markRaw(empty()),
  })
  let request = 0,
    nextId = 0,
    disposed = false
  function sync() {
    const map = getMap()
    if (!map || !ready.value || disposed) return
    if (state.collection.features.length && !map.getSource(GEOJSON_IMPORT_ID))
      map.addSource(GEOJSON_IMPORT_ID, { type: 'geojson', data: state.collection })
    else map.getSource(GEOJSON_IMPORT_ID)?.setData(state.collection)
    if (map.getSource(GEOJSON_IMPORT_ID) && !map.getLayer(GEOJSON_IMPORT_ID))
      map.addLayer({
        id: GEOJSON_IMPORT_ID,
        type: 'fill-extrusion',
        source: GEOJSON_IMPORT_ID,
        paint: {
          'fill-extrusion-color': '#8a8e77',
          'fill-extrusion-height': ['get', 'h'],
          'fill-extrusion-base': 0,
          'fill-extrusion-opacity': 1,
        },
      })
    if (map.getLayer(GEOJSON_IMPORT_ID))
      map.setLayoutProperty(
        GEOJSON_IMPORT_ID,
        'visibility',
        state.enabled && state.collection.features.length ? 'visible' : 'none',
      )
  }
  async function load(input) {
    const current = ++request,
      file = Array.isArray(input) ? input[0] : input
    state.pending = null
    state.properties = []
    state.error = ''
    state.loading = !!file
    if (!file) return
    try {
      const collection = readPolygons(await file.text())
      if (disposed || current !== request) return
      state.pending = markRaw(collection)
      state.properties = propertyNames(collection)
      state.heightKey = state.properties.find((key) => /^(h|height|hauteur|bldg_height)$/i.test(key)) ?? ''
    } catch (error) {
      if (!disposed && current === request) state.error = error.message
    } finally {
      if (!disposed && current === request) state.loading = false
    }
  }
  function apply() {
    state.error = ''
    try {
      if (!ready.value) throw new Error('Wait for the map style to load.')
      if (!state.pending) throw new Error('Choose a GeoJSON polygon file first.')
      const imported = buildingGeojson(state.pending, state.heightKey).features.map((feature) => ({
        ...feature,
        id: feature.id ?? 'import-' + ++nextId,
      }))
      state.collection = markRaw({
        type: 'FeatureCollection',
        features: [...(state.append ? state.collection.features : []), ...imported],
      })
      sync()
    } catch (error) {
      state.error = error.message
    }
  }
  function clear() {
    request++
    state.file = []
    state.pending = null
    state.properties = []
    state.collection = markRaw(empty())
    state.error = ''
    state.loading = false
    sync()
  }
  function restore() {
    try {
      sync()
    } catch {
      state.error = 'Could not display imported GeoJSON for this basemap.'
    }
  }
  watch(() => state.enabled, restore)
  onBeforeUnmount(() => {
    disposed = true
    request++
  })
  return { state, load, apply, clear, restore, layerId: GEOJSON_IMPORT_ID }
}
