import { computed, reactive, ref, watch } from 'vue'
import { buildingLayers } from './buildingLayers.js'
import { getShadingLighting, preserveMapBrightness } from './shading.js'

/**
 * Input: getMap(), ready ref, trạng thái bật/tắt và lỗi building từ useMapLayers.
 * Output: state ngày/giờ/ánh sáng cho ShadingHud, apply() và resetStyle() cho vòng đời map.
 * Ví dụ chọn 2026-06-21 / 09:30 -> tính SunCalc tại tâm map và cập nhật lights; tắt trả ánh sáng nền cũ.
 * Chỉ giữ dữ liệu của Shading; không tạo Mapbox hoặc đăng ký vòng render riêng.
 */
export function useShading({ getMap, ready, layerVisibility, layerErrors, importer }) {
  const localNow = new Date(Date.now() - new Date().getTimezoneOffset() * 60000).toISOString()
  const shading = reactive({
    enabled: false,
    date: localNow.slice(0, 10),
    time: localNow.slice(11, 16),
    sunlight: false,
  })
  /**
   * VaDateInput/VaTimeInput nhận Date theo giờ địa phương; logic Shading giữ chuỗi
   * YYYY-MM-DD/HH:mm. Hai computed chỉ đổi định dạng ở ranh giới UI, không đổi UTC.
   * Ví dụ chọn 21/06/2026 và 09:30 -> shading.date="2026-06-21", time="09:30".
   * Clear trả chuỗi rỗng để validator báo lỗi; không âm thầm dùng ngày/giờ hiện tại.
   * Ngày picker dùng 12:00, giờ picker dùng 01/01/2000 để tách việc chọn từng phần;
   * parseShadingDate vẫn kiểm tra DST trên ngày + giờ thực sự do người dùng chọn.
   */
  const shadingDate = computed({
    get: () => (shading.date ? new Date(shading.date + 'T12:00:00') : null),
    set: (value) => {
      shading.date = value
        ? new Date(value.getTime() - value.getTimezoneOffset() * 60000).toISOString().slice(0, 10)
        : ''
    },
  })
  const shadingTime = computed({
    get: () => (shading.time ? new Date('2000-01-01T' + shading.time + ':00') : null),
    set: (value) => {
      shading.time = value ? value.toTimeString().slice(0, 5) : ''
    },
  })
  const sunPosition = ref(null)
  const shadingError = ref('')
  const timeZone = Intl.DateTimeFormat().resolvedOptions().timeZone
  const shadingLayers = computed(() => [
    ...buildingLayers.filter(
      (entry) => entry.layer.type === 'fill-extrusion' && layerVisibility[entry.id] && !layerErrors[entry.id],
    ),
    ...(importer.geojson.state.enabled && importer.geojson.state.collection.features.length
      ? [{ id: importer.geojson.layerId, label: 'Imported GeoJSON' }]
      : []),
  ])

  let originalLights = null
  let originalSurfacePaint = []
  let shadingApplied = false

  /**
   * Output: bỏ ánh sáng 3D do Shading thêm rồi khôi phục cấu hình gốc của style.
   * Mapbox 3 trả [{type:'flat', ...}] cho nền cũ, nhưng setLights(flat) chỉ cập nhật
   * ánh sáng legacy, KHÔNG gỡ ambient/directional. Phải clear bằng null trước;
   * nếu không, tắt công tắc mà hình ảnh vẫn bị chiếu sáng bởi Shading.
   */
  function restoreShadingLighting() {
    const map = getMap()
    if (!map || !shadingApplied) return
    map.setLights(null)
    if (originalLights) map.setLights(originalLights)
    for (const [id, property, value] of originalSurfacePaint) {
      if (map.getLayer(id)) map.setPaintProperty(id, property, value)
    }
    originalSurfacePaint = []
    shadingApplied = false
  }

  /**
   * Input: shading từ HUD + tâm map hiện tại. Output: setLights và sunPosition.
   * Khi tắt hoặc input lỗi, trả đúng ánh sáng của style trước khi bật Shading.
   * Chỉ chạy khi style sẵn sàng; không đọc painter/sourceCaches/buffer nội bộ.
   */
  function applyShading() {
    const map = getMap()
    if (!map || !ready.value) return
    shadingError.value = ''
    if (!shading.enabled) {
      restoreShadingLighting()
      sunPosition.value = null
      return
    }
    try {
      const result = getShadingLighting(shading, map.getCenter().wrap())
      if (!shadingApplied) originalSurfacePaint = preserveMapBrightness(map)
      map.setLights(result.lights)
      sunPosition.value = result.position
      shadingApplied = true
    } catch {
      restoreShadingLighting()
      sunPosition.value = null
      shadingError.value = 'Choose a valid local date and time (1950 or later).'
    }
  }

  /** style.load -> bỏ snapshot style cũ và ghi lights mới; owner gọi apply() sau khi ready=true. */
  function resetStyle() {
    originalLights = getMap().getLights()
    originalSurfacePaint = []
    shadingApplied = false
  }

  watch(shading, applyShading)
  return {
    shading,
    shadingDate,
    shadingTime,
    sunPosition,
    shadingError,
    shadingLayers,
    timeZone,
    apply: applyShading,
    resetStyle,
  }
}
