import { markRaw, onBeforeUnmount, reactive, watch } from 'vue'
import { useModal } from 'vuestic-ui'
import MapboxDraw from '@mapbox/mapbox-gl-draw'
import { bboxRegion, createExportFiles, resolveRegion, selectBuildings, validLngLat } from './stlExport.js'
import { propertyNames } from '../visualize/csvBesData.js'
import { parseSTL } from '../../preprocessing/stl-converter/stlio.js'
import { zipFiles } from '../../preprocessing/shared/archive.js'
import { downloadFile } from '../../preprocessing/shared/download.js'

/**
 * Input: cùng Mapbox của City, ready ref và bộ Visualize (để biết overlay nào đang hiển thị).
 * Output: state Export + chọn vùng/preview/download. Draw chỉ điều khiển tương tác; core hình học nằm trong stlExport.js.
 * Export thu thập feature đang được render, vì vậy UI luôn thông báo giới hạn viewport/zoom/tiles.
 */
export function useStlExport({ getMap, ready, visualization, importer }) {
  const state = reactive({
    enabled: false,
    mode: 'polygon',
    p1Lng: -73.58,
    p1Lat: 45.49,
    p2Lng: -73.55,
    p2Lat: 45.51,
    concordia: true,
    osm: true,
    geojson: false,
    includeAdditionalModels: false,
    importedGeojson: true,
    includeImportedModels: false,
    customOrigin: false,
    originLng: '',
    originLat: '',
    projection: 'local',
    domain: false,
    info: false,
    position: true,
    yearKey: '',
    typeKey: '',
    // File chọn thêm ở Export khác snapshot model đã Apply từ Import.
    additionalModels: [],
    files: [],
    loadingModels: false,
    polygon: null,
    drawing: false,
    preview: null,
    properties: [],
    warning: '',
    error: '',
    message: '',
    busy: false,
    progress: 0,
    progressLabel: '',
  })
  const { confirm } = useModal()
  let draw = null,
    disposed = false,
    cancelled = false,
    modelRequest = 0

  function readDrawing(event) {
    if (disposed || !draw) return
    if (event?.features?.length && event.type === 'draw.create') {
      const newest = event.features.at(-1)
      for (const feature of draw.getAll().features) if (feature.id !== newest.id) draw.delete(feature.id)
    }
    if (event?.type === 'draw.update') state.mode = 'polygon'
    const polygon = draw.getAll().features.find((feature) => feature.geometry.type === 'Polygon') ?? null
    state.polygon = polygon ? markRaw(polygon) : null
    state.preview = null
    state.properties = []
    state.error = ''
  }

  function drawMode(event) {
    state.drawing = event.mode === 'draw_polygon' || event.mode === 'direct_select'
  }

  /** Draw không tạo bộ nút riêng; VaButton trong HUD gọi API changeMode/deleteAll của thư viện. */
  function ensureDraw() {
    const map = getMap()
    if (!map || !ready.value) throw new Error('Wait for the map style to load.')
    if (!draw) {
      draw = new MapboxDraw({ displayControlsDefault: false, controls: {}, boxSelect: false })
      map.addControl(draw, 'bottom-left')
      map.on('draw.create', readDrawing)
      map.on('draw.update', readDrawing)
      map.on('draw.delete', readDrawing)
      map.on('draw.modechange', drawMode)
      if (state.polygon) draw.add(state.polygon)
    }
    return draw
  }

  function detachDraw() {
    const map = getMap()
    if (!draw || !map) return
    map.off('draw.create', readDrawing)
    map.off('draw.update', readDrawing)
    map.off('draw.delete', readDrawing)
    map.off('draw.modechange', drawMode)
    map.removeControl(draw)
    draw = null
    state.drawing = false
  }

  function drawRegion() {
    try {
      state.mode = 'polygon'
      state.error = ''
      ensureDraw().changeMode('draw_polygon')
      state.drawing = true
    } catch (error) {
      state.error = error.message
    }
  }

  function clearRegion() {
    draw?.deleteAll()
    if (draw) draw.changeMode('simple_select')
    state.polygon = null
    state.preview = null
    state.properties = []
    state.drawing = false
    state.warning = ''
    state.error = ''
  }

  function region() {
    if (state.mode === 'bbox') return resolveRegion(bboxRegion([state.p1Lng, state.p1Lat], [state.p2Lng, state.p2Lat]))
    if (!state.polygon) return null
    return resolveRegion(state.polygon)
  }

  function showBounds() {
    try {
      const selected = region()
      if (!selected) throw new Error('Draw a polygon on the map first.')
      const tool = ensureDraw()
      tool.deleteAll()
      tool.add(selected.polygon)
      tool.changeMode('simple_select')
      state.polygon = markRaw(selected.polygon)
      getMap().fitBounds(
        [
          [selected.bounds[0], selected.bounds[1]],
          [selected.bounds[2], selected.bounds[3]],
        ],
        { padding: 60, maxZoom: 17 },
      )
      state.error = ''
    } catch (error) {
      state.error = error.message
    }
  }

  /** Snapshot STL đã Apply từ Import cộng với file bổ sung của Export, theo các checkbox nguồn. */
  function selectedModels() {
    return [
      ...(state.includeAdditionalModels ? state.additionalModels.filter((model) => model.parsed) : []),
      ...(state.includeImportedModels ? importer.stl.exportModels() : []),
    ]
  }

  /**
   * Input: checkbox nguồn + vùng hiện tại. Output: snapshot collection/center/skipped và warnings.
   * Query dùng cả 4 góc project để bbox pixel vẫn bao hết vùng khi map xoay; không chỉ dùng SW/NE như code cũ.
   */
  function collect() {
    const map = getMap()
    if (!map || !ready.value) throw new Error('Wait for the map to finish loading.')
    const selected = region(),
      models = selectedModels()
    if (!selected && !models.length) throw new Error('Draw a polygon, enter two corners, or add STL models first.')
    if (!selected)
      return {
        collection: { type: 'FeatureCollection', features: [] },
        center: validLngLat(models[0].lng, models[0].lat),
        skipped: 0,
      }
    const ids = []
    if (state.concordia) ids.push('city-concordia-2d', 'city-concordia-3d')
    if (state.osm) ids.push('city-osm-3d')
    if (state.geojson) ids.push(...visualization.exportLayerIds())
    if (state.importedGeojson) ids.push(...importer.exportLayerIds())
    const visible = ids.filter(
      (id) =>
        map.getLayer(id) &&
        map.getLayoutProperty(id, 'visibility') !== 'none' &&
        map.getZoom() >= (map.getLayer(id).minzoom ?? 0),
    )
    const [west, south, east, north] = selected.bounds
    const points = [
      [west, south],
      [east, south],
      [east, north],
      [west, north],
    ].map((point) => map.project(point))
    const canvas = map.getCanvas(),
      width = canvas.clientWidth,
      height = canvas.clientHeight
    const x0 = Math.max(0, Math.min(...points.map((p) => p.x))),
      y0 = Math.max(0, Math.min(...points.map((p) => p.y)))
    const x1 = Math.min(width, Math.max(...points.map((p) => p.x))),
      y1 = Math.min(height, Math.max(...points.map((p) => p.y)))
    const raw =
      visible.length && x1 >= x0 && y1 >= y0
        ? map.queryRenderedFeatures(
            [
              [x0, y0],
              [x1, y1],
            ],
            { layers: visible },
          )
        : []
    const result = selectBuildings(raw, selected)
    const bounds = map.getBounds(),
      warnings = []
    if (west < bounds.getWest() || south < bounds.getSouth() || east > bounds.getEast() || north > bounds.getNorth())
      warnings.push('Part of the region is off-screen; only rendered buildings are collected.')
    if (!map.areTilesLoaded()) warnings.push('Some map tiles are still loading. Preview again once loading finishes.')
    if (state.osm && !visible.includes('city-osm-3d'))
      warnings.push('OSM 3D must be enabled and zoomed to level 15 or higher to be included.')
    if (state.concordia && !visible.some((id) => id.startsWith('city-concordia')))
      warnings.push('Enable a Concordia layer to include its buildings.')
    if (result.skipped)
      warnings.push(result.skipped + ' features without usable building height/geometry were skipped.')
    state.warning = warnings.join(' ')
    return { ...result, center: selected.center }
  }

  function preview() {
    if (state.busy) return
    state.error = ''
    state.message = ''
    try {
      const selected = collect()
      state.preview = markRaw(selected)
      state.properties = propertyNames(selected.collection)
      if (!selected.collection.features.length && !selectedModels().length)
        state.error = 'No buildings found. Check the region, visible layers and zoom.'
    } catch (error) {
      state.error = error.message
      state.preview = null
      state.properties = []
    }
  }

  /** Input: nhiều STL ASCII/binary. Output: model hợp lệ + vị trí riêng; file lỗi giữ message, không ngăn xuất các file hợp lệ khác. */
  async function loadAdditionalModels(input) {
    const files = input ? (Array.isArray(input) ? input : [input]) : []
    const request = ++modelRequest,
      previous = state.additionalModels,
      models = []
    state.loadingModels = true
    state.error = ''
    for (const file of files) {
      const existing = previous.find((model) => model.file === file)
      if (existing) {
        models.push(existing)
        continue
      }
      const center = getMap()?.getCenter() ?? { lng: -73.5673, lat: 45.5017 }
      try {
        const parsed = parseSTL(await file.arrayBuffer(), file.name.replace(/\.[^.]+$/, ''))
        models.push({
          file: markRaw(file),
          name: file.name,
          parsed: markRaw(parsed),
          lng: center.lng,
          lat: center.lat,
          error: '',
        })
      } catch (error) {
        models.push({ file: markRaw(file), name: file.name, parsed: null, error: error.message })
      }
      if (disposed || request !== modelRequest) return
    }
    if (!disposed && request === modelRequest) {
      state.additionalModels = models
      state.loadingModels = false
    }
  }

  /** Output: hủy ở lần yield tiếp theo và không download ZIP chưa hoàn tất. */
  function cancel() {
    cancelled = true
  }

  /**
   * Snapshot vùng/map trước khi dựng hình; giữ trục STL X đông/Y lên/Z nam, quy ước origin và filenames cũ.
   * ZIP là một lần download để browser không chặn chuỗi nhiều file; Cancel/unmount không tạo file đầu ra dở dang.
   */
  async function exportZip() {
    if (state.busy || state.loadingModels) return
    state.busy = true
    cancelled = false
    state.progress = 0
    state.progressLabel = 'Collecting buildings…'
    state.error = ''
    state.message = ''
    try {
      await new Promise((resolve) => setTimeout(resolve, 0))
      if (disposed || cancelled) return
      const selected = collect()
      state.preview = markRaw(selected)
      state.properties = propertyNames(selected.collection)
      if (
        selected.collection.features.length > 20000 &&
        !(await confirm({
          title: 'Large STL export',
          message: selected.collection.features.length + ' buildings will create a large file. Continue?',
          size: 'small',
        }))
      )
        return
      if (disposed || cancelled) return
      const options = {
        origin: state.customOrigin ? validLngLat(state.originLng, state.originLat) : selected.center,
        projection: state.projection,
        extraModels: selectedModels(),
        domain: state.domain,
        info: state.info,
        position: state.position,
        yearKey: state.yearKey,
        typeKey: state.typeKey,
      }
      const output = await createExportFiles(selected.collection, options, {
        batchSize: 250,
        shouldCancel: () => cancelled || disposed,
        onProgress: (done, total) => {
          state.progress = total ? Math.round((done / total) * 90) : 0
          state.progressLabel = done + ' / ' + total + ' buildings'
        },
      })
      state.progressLabel = 'Preparing ZIP…'
      state.progress = 95
      const zip = await zipFiles(output.files)
      if (disposed || cancelled) {
        state.message = 'Export cancelled.'
        return
      }
      downloadFile(zip, 'city-export.zip', 'application/zip')
      state.progress = 100
      state.message =
        'Exported ' +
        output.result.stats.buildings +
        ' buildings and ' +
        output.result.stats.imported +
        ' STL solids (' +
        output.result.stats.triangles +
        ' facets).'
    } catch (error) {
      if (!disposed) {
        if (cancelled || error.cancelled) state.message = 'Export cancelled.'
        else state.error = error.message
      }
    } finally {
      state.busy = false
    }
  }

  /** Bỏ Draw trước setStyle để thư viện không giữ control/source cũ; polygon và lựa chọn Vue vẫn còn. */
  function beforeStyleChange() {
    detachDraw()
  }
  function restore() {
    if (state.enabled && state.polygon) {
      try {
        ensureDraw()
      } catch (error) {
        state.error = error.message
      }
    }
  }
  function sourceError(id) {
    if (!id?.startsWith('mapbox-gl-draw')) return false
    state.error = 'Could not render the selection region.'
    return true
  }
  watch(
    () => state.enabled,
    (enabled) => {
      if (!enabled) {
        cancel()
        detachDraw()
      } else restore()
    },
  )
  onBeforeUnmount(() => {
    disposed = true
    cancelled = true
    modelRequest++
    detachDraw()
  })

  return {
    state,
    drawRegion,
    clearRegion,
    showBounds,
    preview,
    loadAdditionalModels,
    exportZip,
    cancel,
    beforeStyleChange,
    restore,
    sourceError,
    handlesClick: () => state.drawing,
  }
}
