import { coordEach } from '@turf/meta'
import { numeric, readPolygons, validateCrs } from '../visualize/csvBesData.js'

export const GEOJSON_IMPORT_ID = 'city-import-geojson'
export const REST_IMPORT_ID = 'city-import-rest'

/** Input: tọa độ UI/API. Output: [lng,lat] WGS84 hữu hạn trong giới hạn Mercator; input trống/NaN bị từ chối. */
export function importPosition(lng, lat) {
  const point = [numeric(lng), numeric(lat)]
  if (point.some((v) => v === null) || Math.abs(point[0]) > 180 || Math.abs(point[1]) > 85.051129)
    throw new Error('Use valid WGS84 longitude and latitude within the Mercator map.')
  return point
}

/** Input: nội dung positionSetting.txt. Output: origin/projection STL; Point là WGS84, không phải tọa độ Web Mercator. */
export function stlPosition(text) {
  const feature = JSON.parse(text.replace(/^\uFEFF/, ''))
  validateCrs(feature)
  const point = feature?.type === 'Feature' && feature.geometry?.type === 'Point' ? feature.geometry.coordinates : null
  if (!Array.isArray(point) || point.length < 2 || !point.slice(0, 2).every(Number.isFinite))
    throw new Error('Position file must be a WGS84 GeoJSON Point feature.')
  const origin = importPosition(point[0], point[1])
  const projection = feature.properties?.projection ?? 'local'
  if (!['local', 'web-mercator'].includes(projection)) throw new Error('Unsupported STL projection in position file.')
  return { origin, projection }
}

/** Input: collection đã readPolygons, cột chiều cao. Output: clone properties.h; thiếu/sai/âm -> 10m như bản cũ. */
export function buildingGeojson(collection, heightKey) {
  return {
    type: 'FeatureCollection',
    features: collection.features.map((feature) => {
      const height = Number.parseFloat(feature.properties?.[heightKey])
      return {
        ...feature,
        properties: { ...feature.properties, h: Number.isFinite(height) && height > 0 ? height : 10 },
      }
    }),
  }
}

/** Input: JSON và JSON Pointer (/items/0/lat, chuỗi rỗng = root). Output: giá trị own-property, không eval hoặc đi qua prototype. */
export function jsonValue(data, pointer) {
  if (pointer === '') return data
  if (typeof pointer !== 'string' || !pointer.startsWith('/')) throw new Error('Select a JSON field first.')
  for (const part of pointer
    .slice(1)
    .split('/')
    .map((key) => key.replace(/~1/g, '/').replace(/~0/g, '~'))) {
    if (data === null || typeof data !== 'object' || !Object.hasOwn(data, part))
      throw new Error('The selected JSON field no longer exists.')
    data = data[part]
  }
  return data
}

/** Input: JSON response. Output: Vuestic tree + options {id:JSON Pointer,label}; dùng cùng path khi refresh để không lệch giá trị. */
export function jsonFields(data) {
  const options = []
  // shortcut: tree tối đa 10.000 node/40 cấp; dùng lazy tree cho API lớn hơn thay vì dựng toàn bộ DOM.
  function node(value, id, name, depth) {
    if (options.length >= 10000 || depth > 40) throw new Error('JSON tree is too large (10,000 nodes / 40 levels).')
    const label = name + (value !== null && typeof value === 'object' ? '' : ' : ' + String(value).slice(0, 80))
    options.push({ id, label: id || '$' })
    const children =
      value !== null && typeof value === 'object'
        ? Object.entries(value).map(([key, child]) =>
            node(child, id + '/' + key.replace(/~/g, '~0').replace(/\//g, '~1'), key, depth + 1),
          )
        : []
    return { id, label, ...(children.length ? { children } : {}) }
  }
  return { tree: [node(data, '', '$', 0)], options }
}

/** Input: root/Feature/geometry/array được chọn trong API. Output: GeoJSON features đã kiểm tra tọa độ và cấu trúc. */
export function restFeatures(value, depth = 0) {
  if (depth > 30 || !value || typeof value !== 'object')
    throw new Error('Choose a GeoJSON Feature, geometry or FeatureCollection.')
  validateCrs(value)
  if (Array.isArray(value)) return value.flatMap((item) => restFeatures(item, depth + 1))
  if (value.type === 'FeatureCollection') {
    if (!Array.isArray(value.features)) throw new Error('GeoJSON features must be an array.')
    return value.features.flatMap((item) => restFeatures(item, depth + 1))
  }
  const feature = value.type === 'Feature' ? value : { type: 'Feature', properties: {}, geometry: value }
  const geometry = feature.geometry
  if (!geometry) throw new Error('GeoJSON geometry is missing.')
  validateCrs(geometry)
  if (geometry.type === 'GeometryCollection') {
    if (!Array.isArray(geometry.geometries)) throw new Error('Invalid GeometryCollection.')
    return geometry.geometries.flatMap((g) => restFeatures({ ...feature, geometry: g }, depth + 1))
  }
  const c = geometry.coordinates
  if (['Polygon', 'MultiPolygon'].includes(geometry.type))
    readPolygons(JSON.stringify({ type: 'FeatureCollection', features: [feature] }))
  else {
    const point = (p) => Array.isArray(p) && p.length >= 2 && p.every(Number.isFinite)
    const line = (p) => Array.isArray(p) && p.length >= 2 && p.every(point)
    const valid =
      geometry.type === 'Point'
        ? point(c)
        : geometry.type === 'MultiPoint'
          ? Array.isArray(c) && c.length > 0 && c.every(point)
          : geometry.type === 'LineString'
            ? line(c)
            : geometry.type === 'MultiLineString'
              ? Array.isArray(c) && c.length > 0 && c.every(line)
              : false
    if (!valid) throw new Error('Unsupported or invalid GeoJSON geometry.')
    coordEach(feature, (p) => importPosition(p[0], p[1]))
  }
  if (
    feature.id !== undefined &&
    (!['string', 'number'].includes(typeof feature.id) ||
      (typeof feature.id === 'number' && !Number.isFinite(feature.id)))
  )
    throw new Error('GeoJSON IDs must be strings or numbers.')
  return [{ ...feature, properties: { ...feature.properties } }]
}

/** Input: scalar latitude/longitude/value đã chọn. Output: một Point; giá trị null/0 vẫn được giữ. */
export function restPoint(lat, lng, value) {
  if (
    (typeof value === 'number' && !Number.isFinite(value)) ||
    (value !== null && !['string', 'number', 'boolean'].includes(typeof value))
  )
    throw new Error('Choose a scalar value for the point.')
  return { type: 'Feature', properties: { value }, geometry: { type: 'Point', coordinates: importPosition(lng, lat) } }
}

/** Input: URL nhập từ UI. Output: http(s) URL; không nhận script/file URL hoặc username/password trong URL. */
export function restUrl(value) {
  let url
  try {
    url = new URL(value.trim())
  } catch {
    throw new Error('Enter a valid HTTP or HTTPS URL.')
  }
  if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password)
    throw new Error('Use an HTTP/HTTPS URL without embedded credentials.')
  return url.href
}
